INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H8127', 'spa', 'Diente o dientes; marfil; peñasco escarpado o risco puntiagudo; también un tenedor (para carne). Parte de la imagen física de una punta afilada y sali', 'Diente o dientes; marfil; peñasco escarpado o risco puntiagudo; también un tenedor (para carne). Parte de la imagen física de una punta afilada y saliente. שֵׁן comienza en la boca y se proyecta hacia afuera. En su núcleo significa ''diente'' —la parte del cuerpo que muerde, rechina y tritura— y este sentido anatómico concreto domina sus 55 apariciones. La ley del talión lo consagra en fórmula jurídica: ''diente por diente'' (Éx 21:24; Lv 24:20; Dt 19:21). Pero el hebreo veía la forma del diente por todas partes. Los colmillos de elefante dieron שֵׁן como palabra para ''marfil'', el material de lujo del trono de Salomón (1 R 10:18) y las opulentas ''casas de marfil'' denunciadas por Amós (3:15). Las formaciones rocosas dentadas también se llamaron שֵׁן: los dos riscos que flanquean el paso de Micmas en 1 Samuel 14:4-5 son literalmente ''dientes'' de piedra. Una curiosa aparición aislada en 1 Samuel 2:13 nos da el tenedor de tres puntas, otro instrumento puntiagudo con forma de diente.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H8128', 'spa', 'Diente, dientes (arameo); los dientes de hierro de la bestia terrible en las visiones de Daniel', 'Este sustantivo arameo que significa ''diente'' aparece exclusivamente en las visiones apocalípticas de Daniel sobre las cuatro bestias. La forma dual שִׁנַּיִן designa hileras de dientes, concretamente los grandes dientes de hierro de la cuarta bestia que devora y tritura todo (Dan 7:7, 19). La forma singular con sufijo describe los dientes de la segunda bestia semejante a un oso con costillas en su boca (Dan 7:5). En estas visiones, los dientes funcionan como símbolos del poder destructor de los imperios. La clasificación bajo TIEMPO en los datos refleja confusión con el homógrafo שְׁנָה (''año''), pero el significado real es inequívocamente ''dientes''.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H8130', 'spa', 'Odiar, aborrecer, sentir aversión; como participio: enemigo, adversario; en pasivo: aborrecida, desfavorecida', 'Verbo de repulsión emocional visceral que abarca desde la animosidad personal hasta la abominación teológica. En su uso más frecuente describe un odio activo dirigido contra personas o prácticas que Dios considera detestables (Dt 12:31, Sal 5:5). El participio activo funciona con frecuencia como sustantivo, ''enemigo'' — los que me odian, los que te odian, los que odian a Dios — en contextos militares, legales y sálmicos. Un conmovedor uso doméstico aparece en el participio pasivo que describe a la ''esposa aborrecida'' de la ley matrimonial patriarcal (Gn 29:31; Dt 21:15), donde el árabe مَكْرُوهَة y el español aborrecida confirman un sentido de rechazo emocional más que de mera preferencia.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H8132', 'spa', 'cambiar, alterar, transformar (cognado arameo del hebreo shanah)', 'Este verbo arameo significa cambiar o alterar algo de su estado previo. Aparece en tres contextos llamativos: el color de Nabucodonosor cambiando cuando enloqueció (2 Reyes 25:29, o posiblemente las vestiduras de Joaquín siendo cambiadas), la observación de Cohelet de que la sabiduría ''cambia'' el rostro de una persona (Eclesiastés 8:1), y el lamento de Jeremías de que el oro ''ha cambiado'' o se ha oscurecido (Lamentaciones 4:1). La raíz se conecta con la familia más amplia de palabras semíticas sobre transformación, incluyendo la posible derivación de ''año'' (shanah) de las estaciones cambiantes. El Piel y otros temas derivados intensifican el sentido de alteración deliberada.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H8133', 'spa', 'Cambiar, ser alterado o ser diferente; verbo arameo usado para transformaciones de apariencia, carácter o decretos en Daniel y Esdras', 'Cambiar, ser alterado o ser diferente; verbo arameo usado para transformaciones de apariencia, carácter o decretos en Daniel y Esdras');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H8135', 'spa', 'Odio; hostilidad profunda o aversión, ya sea enemistad humana, repulsión sexual o desagrado divino. El sustantivo abstracto principal para el odio en ', 'Odio; hostilidad profunda o aversión, ya sea enemistad humana, repulsión sexual o desagrado divino. El sustantivo abstracto principal para el odio en la Biblia hebrea, שִׂנְאָה abarca un espectro que va desde la animosidad personal hasta la enemistad entre naciones y el juicio teológico. Proverbios lo contrasta con el amor: ''el odio despierta rencillas, mas el amor cubrirá todas las faltas'' (Prov 10:12). En 2 Samuel 13:15 designa la violenta repulsión sexual que Amnón sintió hacia Tamar, un odio ''mayor que el amor'' que había fingido. Los Salmos lo aplican a la hostilidad que rodea al justo (Sal 25:19; 109:3, 5), y Deuteronomio lo usa para describir la acusación infiel de Israel contra el SEÑOR (Deut 1:27; 9:28).');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H8138a', 'spa', 'Cambiar, alterar, ser diferente; también disfrazarse, pervertir o trasladar de un lugar a otro. Verbo hebreo versátil arraigado en la idea de transfor', 'Cambiar, alterar, ser diferente; también disfrazarse, pervertir o trasladar de un lugar a otro. Verbo hebreo versátil arraigado en la idea de transformación y alteración. En su forma Piel cambia algo activamente —un nombre, un comportamiento, un decreto—, mientras que el Qal capta el sentido intransitivo de ser diferente o experimentar cambio. El Hitpael reflexivo ilustra vívidamente a alguien que altera su propia apariencia para volverse irreconocible, como cuando la esposa de Jeroboam se disfrazó (1 R 14:2). La misma raíz puede oscurecerse hacia el sentido de pervertir la justicia (Pr 31:5) o aligerarse hacia el significado práctico de trasladar a alguien a un nuevo lugar (Est 2:9).');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H8138b', 'spa', 'Repetir o hacer de nuevo; realizar una acción por segunda vez, ya sea un acto físico o una palabra pronunciada.', 'Verbo que transmite la idea de hacer algo por segunda vez o repetir una acción. En contextos narrativos, aparece frecuentemente tras un golpe decisivo: Abner hirió a un hombre sin necesidad de golpear otra vez (2 Sam 20:10), y el compañero de David le aseguró que no necesitaría repetir la estocada contra Saúl (1 Sam 26:8). Elías ordena dramáticamente a los siervos que viertan agua una segunda vez y luego una tercera (1 Re 18:34). El cognado árabe que significa ''doblar, plegar, duplicar'' ilumina la noción central de la raíz: volver sobre una acción ya realizada.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H8140', 'spa', 'año — sustantivo arameo para una unidad de tiempo de doce meses, usado en datación y duración', 'שְׁנָה (shenah) es el cognado arameo del hebreo שָׁנָה (shanah), que aparece siete veces en las porciones arameas de Esdras y Daniel. Se emplea exclusivamente para referencia cronológica: para fechar decretos reales (''en el primer año de Ciro'', Esd 5:13), marcar hitos de construcción (''en el sexto año'', Esd 6:15) y señalar duraciones (''muchos años'', Esd 5:11). El plural שְׁנִין aparece para ''sesenta y dos años'' en Daniel 6:1. En todas las lenguas la traducción es directa: español ''año'', francés ''année'', alemán ''Jahr'' — pura medición temporal sin extensión figurada.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H8141', 'spa', 'שָׁנָה -- año; la unidad hebrea primaria para medir períodos de tiempo extensos', 'El sustantivo femenino שָׁנָה (''año'') es el término hebreo fundamental para el cómputo anual del tiempo, con 880 apariciones en todos los géneros y períodos. Estructura genealogías (''Adán vivió 930 años,'' Gn 5:5), fecha reinados (''en el tercer año del rey tal''), marca ciclos agrícolas y litúrgicos (''tres veces al año,'' Éx 23:14) y mide períodos proféticos (''setenta años,'' Jr 25:11). La palabra aparece en formas de singular, dual (שְׁנָתַיִם, ''dos años'') y plural, con cadenas constructas y todo tipo de prefijos preposicionales, sin que ninguna de estas flexiones genere sentidos distintos.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H8142', 'spa', 'Sueño, somnolencia; el estado de reposo corporal y conciencia reducida, usado literal y figuradamente para la negligencia', 'Sueño, somnolencia; el estado de reposo corporal y conciencia reducida, usado literal y figuradamente para la negligencia');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H8144', 'spa', 'Escarlata, carmesí; el vívido color rojo o tinte derivado del insecto quermes, usado para telas, vestiduras e hilos', 'Escarlata, carmesí; el vívido color rojo o tinte derivado del insecto quermes, usado para telas, vestiduras e hilos');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H8145', 'spa', 'Segundo (numeral ordinal); adverbialmente ''por segunda vez''; en un caso aislado, borde o labio (1 R 7:23)', 'Numeral ordinal común que significa ''segundo'', con formas masculina (שֵׁנִי) y femenina (שֵׁנִית) a lo largo de toda la Biblia hebrea. Marca secuencia temporal (''el segundo día'', ''el segundo año''), rango (''el segundo hijo'') y repetición (''por segunda vez'', como en Gn 22:15, donde el ángel llama a Abraham de nuevo). Las traducciones en distintas lenguas lo vierten de manera uniforme como ordinal: español ''el segundo'', francés ''le deuxième'', alemán ''der zweite'', confirmando su perfil semántico homogéneo. Una aparición en 1 Reyes 7:23 parece reflejar un homógrafo con el significado de ''borde, labio'' en lugar del ordinal.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H8147', 'spa', 'Dos, ambos, un par; numeral cardinal para dos en formas duales masculina y femenina, también en números compuestos', 'שְׁנַיִם (masculino) y שְׁתַּיִם (femenino) son las formas duales del numeral cardinal hebreo dos, entre los numerales más frecuentes de las Escrituras con 769 apariciones. Más allá del conteo simple, esta palabra abarca un rango semántico notable. Con sufijos pronominales se convierte en el pronombre ''ambos'' (שְׁנֵיהֶם), pasando de la aritmética a la totalidad. En estado constructo con עָשָׂר/עֶשְׂרֵה forma el compuesto ''doce,'' número de enorme significado bíblico: doce tribus, doce apóstoles, doce puertas de la nueva Jerusalén. Un grupo reducido pero jurídicamente significativo significa ''el doble,'' como en las leyes de restitución de Éxodo 22.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H8148', 'spa', 'Palabra hiriente, escarnio, refrán de burla; dicho cortante que convierte a alguien en objeto de mofa entre las naciones', 'Este sustantivo designa palabras hirientes y cortantes, en particular burlas o refranes que convierten a alguien en objeto de escarnio público. Aparece en contextos de maldición pactual y juicio divino. Deuteronomio 28:37 advierte que Israel desobediente llegará a ser «espanto, proverbio y burla entre todos los pueblos». 1 Reyes 9:7 y 2 Crónicas 7:20 repiten la advertencia respecto al templo. Jeremías 24:9 pronuncia el mismo destino sobre los que permanezcan en la tierra. Se trata de humillación verbal codificada en forma proverbial: cuando el nombre de un pueblo se convierte en sinónimo de vergüenza entre las naciones.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H8149', 'spa', 'Senir; nombre amorreo del monte Hermón (o de sus cumbres septentrionales), fuente de madera de ciprés', 'Este es el nombre amorreo para el monte Hermón, o posiblemente para sus cumbres septentrionales. Deuteronomio 3:9 explica que «los sidonios llaman a Hermón Sirión, pero los amorreos lo llaman Senir», preservando las variantes regionales del nombre. Cantar de los Cantares 4:8 invoca poéticamente «la cumbre de Senir y del Hermón» como alturas remotas y salvajes. 1 Crónicas 5:23 lo usa como referencia geográfica fronteriza. Ezequiel 27:5 menciona que los constructores de barcos de Tiro empleaban ciprés de Senir para sus tablones. Este topónimo amorreo refleja la realidad multiétnica del antiguo Cercano Oriente, donde las montañas recibían nombres distintos según cada pueblo.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H8150', 'spa', 'Afilar, aguzar (una hoja o la lengua); enseñar diligentemente mediante repetición; ser traspasado interiormente.', 'En su raíz, este verbo significa hacer algo cortante: ya sea el filo de una espada, la punta de una flecha o el aguijón punzante del habla hostil. Los salmistas lo emplean repetidamente para lenguas ''afiladas como espadas'' (Sal 64:3; 140:3), fusionando los sentidos físico y verbal de cortar. En Deuteronomio 32:41, Dios mismo afila su espada reluciente para el juicio. Quizá el uso más querido es el Piel de Deuteronomio 6:7 — ''las repetirás a tus hijos'' — donde la metáfora pasa de afilar hojas a grabar palabras indeleblemente en los corazones, como quien cincelara en piedra.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H8152', 'spa', 'Sinar — la antigua región mesopotámica asociada con Babel y Babilonia, la llanura del primer asentamiento humano y posterior exilio', 'Se refiere a la tierra de Sinar, el nombre bíblico para el sur de Mesopotamia que abarca el territorio de Babel y la posterior Babilonia. Aparece por primera vez como escenario de la urbanización más temprana de la humanidad tras el diluvio (Gn 10:10; 11:2) y la narrativa de la Torre de Babel. En los textos proféticos se convierte en símbolo de exilio y juicio divino: Daniel fue llevado a la ''tierra de Sinar'' (Dn 1:2), y Zacarías contempla la maldad transportada allí en una canasta (Zac 5:11). La Septuaginta lo traduce generalmente como Σεννααρ, mientras que el texto griego de Zacarías sustituye directamente ''Babilonia'', confirmando la identificación que los lectores antiguos daban por sentada.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H8154', 'spa', 'Saquear, despojar; apoderarse de bienes por la fuerza, como asaltantes y conquistadores', 'Sinónimo menos frecuente de shalal y bazaz, este verbo denota la incautación violenta de bienes, describiendo a menudo a asaltantes e invasores. El participio Qal funciona frecuentemente como sustantivo —«saqueadores»— como en Jueces 2:14, donde Dios entrega a Israel en manos de quienes los saquean. Isaías 17:14 lo empareja con bozezenu («nuestros despojadores»), mostrando cómo el hebreo emplea cuasi-sinónimos para dar énfasis. El participio pasivo en Isaías 42:22 invierte la perspectiva: Israel mismo se convierte en «saqueado», un pueblo robado y despojado. Isaías 10:13 intensifica la acción en Piel, donde el rey asirio se jacta de un saqueo exhaustivo.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H8155', 'spa', 'Saquear, despojar; arrebatar y llevarse posesiones por la fuerza', 'Variante de שָׁסָה, este verbo describe el saqueo violento: la incautación forzosa y el arrastre de bienes y personas. En Jueces 2:14, Dios entrega a Israel en manos de saqueadores que los despojan, y en 1 Samuel 17:53 los israelitas saquean el campamento filisteo tras la derrota de Goliat. El Nifal pasivo aparece en Zacarías 14:2 e Isaías 13:16, donde las casas son saqueadas en el caos de la conquista. El Salmo 89:41 lo emplea para describir al rey humillado a quien todos los que pasan despojan. El verbo español ''saquear'' y el francés ''piller'' captan la violenta expropiación que es el núcleo de este verbo.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H8156', 'spa', 'Hender, partir (pezuñas); desgarrar violentamente; contener o refrenar.', 'Un verbo de división y desgarro que abarca la ley dietética, la narrativa heroica y la moderación moral. Cinco de sus nueve apariciones se encuentran en las leyes alimentarias de Levítico y Deuteronomio, describiendo la ''pezuña hendida'' que distingue a los animales puros de los impuros (Lv 11:3, 7, 26; Dt 14:6-7). En la narrativa de Sansón, el joven héroe despedaza un león como quien despedaza un cabrito (Jue 14:6) — una partición cruda y violenta. Sorprendentemente, la misma raíz aparece cuando David ''contuvo'' a sus hombres de atacar a Saúl (1 Sam 24:7), como si separara y frenara el impulso hacia la violencia.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H8157', 'spa', 'Hendidura, pezuña partida; la división de la pezuña como criterio de animales puros en la ley levítica', 'Este sustantivo se refiere a la hendidura o división de la pezuña, característica clave para determinar qué animales son puros según la ley levítica. Levítico 11:3 define a los animales terrestres puros como aquellos que tienen la pezuña hendida y rumian. El versículo 7 menciona al cerdo, que tiene pezuña hendida pero no rumia, por lo cual es impuro. Deuteronomio 14:6 emplea el mismo lenguaje. La pezuña partida se convirtió en un marcador simbólico que distingue lo puro de lo impuro, ordenando la creación según categorías divinas: una señal física que apunta a distinciones rituales y quizá morales inscritas en el orden creado.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H8159', 'spa', 'Mirar, considerar con favor o atención; también apartar la mirada, consternarse o (de los ojos) oscurecerse —centrado en el acto de la visión dirigida', 'Mirar, considerar con favor o atención; también apartar la mirada, consternarse o (de los ojos) oscurecerse —centrado en el acto de la visión dirigida. En su esencia, este verbo describe una mirada deliberada y evaluativa —no un vistazo casual sino una mirada que transmite juicio o favor. Dios ''miró con agrado'' la ofrenda de Abel pero no ''miró'' la de Caín (Gn 4:4–5), estableciendo el peso teológico del verbo desde su primera aparición. Isaías lo usa para mirar hacia el Santo de Israel con confianza (Is 17:7) o apartar la mirada por dolor (Is 22:4). En Job, el sufriente ruega a Dios que ''aparte la mirada'' y le conceda descanso (Job 7:19; 14:6). La forma Hitpael en Isaías 41:10, 23 extiende el significado a la consternación interior —mirar alrededor con pánico.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H8160', 'spa', 'Hora, momento; unidad breve de tiempo (arameo), usada en Daniel para expresar inmediatez', 'Este sustantivo arameo designa un lapso breve de tiempo --un ''momento'' o una ''hora''-- y aparece solo en el libro de Daniel. La expresión בַּהּ־שַׁעֲתָא (''en esa misma hora/momento'') transmite una inmediatez dramática: en el instante en que suena la música, todos deben postrarse (Dan 3:6, 15); en ese preciso momento se cumple el decreto de Nabucodonosor (Dan 4:33); y los dedos aparecen escribiendo en la pared ''en esa misma hora'' (Dan 5:5). Los cognados en siríaco, árabe y etiópico comparten el sentido de porción medida de tiempo, aunque el uso en el arameo bíblico enfatiza la instantaneidad más que un lapso exacto de sesenta minutos.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H8163b', 'spa', 'Macho cabrío, especialmente como animal sacrificial; raramente, criatura peluda o demonio caprino. Derivado de la raíz que significa ''peludo'' o ''vellu', 'Macho cabrío, especialmente como animal sacrificial; raramente, criatura peluda o demonio caprino. Derivado de la raíz que significa ''peludo'' o ''velludo'', este sustantivo se refiere casi exclusivamente al macho cabrío empleado en el sistema sacrificial de Israel. Aparece de manera prominente en los rituales levíticos de ofrenda por el pecado, incluida la ceremonia del chivo expiatorio en el Día de la Expiación (Lv 16), y a lo largo de las ofrendas tribales de Números 7. Una sola aparición en Daniel 8:21 aplica el término simbólicamente al rey de Grecia, donde ''el peludo'' refleja el vínculo etimológico con la vellosidad más que con el animal cultual.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H8163c', 'spa', 'Sátiro, demonio cabrío; seres sobrenaturales peludos con rasgos caprinos, objetos de culto idolátrico prohibido', 'Este sustantivo designa sátiros o demonios cabríos: entidades sobrenaturales asociadas con lugares desolados o con la adoración idolátrica. Levítico 17:7 prohíbe a Israel sacrificar a los «demonios cabríos» como hacían en Egipto. 2 Crónicas 11:15 condena a Jeroboam por nombrar sacerdotes para ellos. Isaías emplea el término para criaturas que habitan ruinas desoladas: Isaías 13:21 describe Babilonia como lugar donde «danzarán los sátiros», e Isaías 34:14 retrata de modo similar el páramo de Edom. Estos seres desdibujan la frontera entre dioses demoniacos adorados idolátricamente y espíritus del yermo que rondan los lugares abandonados, encarnando el caos y la desolación.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H8165a', 'spa', 'Seir — el territorio montañoso al sureste del mar Muerto, tierra natal de Esaú y los edomitas', 'Seir — el territorio montañoso al sureste del mar Muerto, tierra natal de Esaú y los edomitas');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H8165b', 'spa', 'Seir (nombre personal/territorial: territorio edomita y ancestro horeo)', 'Seir se refiere principalmente a la región montañosa al sur y este del Mar Muerto, tierra natal de Edom y los descendientes de Esaú. El nombre puede derivar de una palabra que significa ''velludo'' o ''cabra'', jugando con la vellosidad de Esaú (Génesis 25:25; 27:11). Génesis 36:20-21 y 1 Crónicas 1:38 listan a Seir también como nombre personal—un jefe horeo y ancestro de los habitantes pre-edomitas de la región. El uso dual (persona y lugar) es típico, con el territorio nombrado según su ancestro epónimo. Algunos eruditos lo conectan con la tierra egipcia/acadia de Šêri. El nombre lleva significado tanto geográfico como genealógico al trazar los orígenes edomitas.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H8168', 'spa', 'hueco de la mano, puñado (palma ahuecada o porción medida)', 'Este sustantivo denota ya sea el hueco de la mano (la palma ahuecada) o la cantidad que cabe en una mano—un puñado. Isaías 40:12 lo usa en una imagen magnífica de Dios ''midiendo las aguas en el hueco de Su mano'', enfatizando la soberanía divina sobre la creación. En contextos hiperbólicos, ''puñados'' se convierte en una figura para cantidad: suficiente polvo en Samaria para dar a cada soldado un puñado (1 Reyes 20:10), o profetisas falsas que profetizan por ''puñados de cebada'' (Ezequiel 13:19). El término captura tanto el rasgo anatómico (la mano ahuecada) como la cantidad medida que puede contener.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H8169', 'spa', 'Saalbín, Saalvim (nombre de lugar: ciudad en el territorio de Dan)', 'Saalbín (o Saalvim) fue una ciudad en el territorio original de Dan, mencionada en contextos de conquista y administración. El nombre posiblemente significa ''guarida de zorros'' según raíces cognadas. Josué 19:42 la incluye en la asignación de Dan. Jueces 1:35 reporta que los amorreos se aferraron a Saalvim (los danitas no lograron conquistarla completamente), aunque eventualmente ''la mano de la casa de José prevaleció'' sobre ellos. 1 Reyes 4:9 la lista en el segundo distrito administrativo de Salomón. La ubicación precisa del sitio es debatida, aunque se encontraba en algún lugar de la Sefelá o la región montañosa al oeste de Jerusalén.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H8172', 'spa', 'Apoyarse en, sostenerse sobre; figuradamente, confiar en o depender de alguien, especialmente de Dios o de aliados humanos', 'Apoyarse en, sostenerse sobre; figuradamente, confiar en o depender de alguien, especialmente de Dios o de aliados humanos');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H8173a', 'spa', 'ser cegado, untado (ojos cerrados/oscurecidos)', 'Este verbo raro significa ser cegado o tener los ojos untados para cerrarlos, siempre usado metafóricamente para la obtusidad espiritual. Isaías 29:9 usa formas tanto en Qal como Hitpalpel en un mandato entrecortado: ''¡Cegaos y estad ciegos!'' (paralelo a ''demoraos y sed demorados''), llamando a Israel a persistir en ignorancia voluntaria. Isaías 6:10 en la comisión de Dios al profeta ordena ''¡embarra sus ojos!''—embota sus ojos. La raíz se relaciona con palabras arameas para untar o alisar. Algunos eruditos sugieren enmiendas textuales, pero el sentido básico de visión oscurecida—ya sea ceguera literal o metafórica—permanece claro en todas las atestaciones.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H8173b', 'spa', 'Deleitarse, gozar intensamente; jugar, divertirse con alegría.', 'El verbo Pilpel שִׁעֲשַׁע (de la raíz שׁעע II) expresa un deleite profundo y prolongado, el tipo de placer que se saborea con calma. Cinco de sus seis apariciones describen deleite espiritual: el salmista se deleita en la Torá de Dios (Sal 119:16, 47, 70) y las consolaciones divinas deleitan al alma atribulada (Sal 94:19). El alemán Wohlgefallen capta perfectamente esa cualidad contemplativa. Pero Isaías ofrece un sexto uso sorprendente: en el reino mesiánico, un niño de pecho juega junto a la cueva de la cobra (Isa 11:8), un deleite inocente e intrépido vuelto físico. Isaías 66:12 añade la tierna imagen de ser acariciado sobre las rodillas, fundiendo consuelo físico con gozo espiritual.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H8175a', 'spa', 'erizarse de horror, estremecerse (cabello se eriza por terror)', 'Este verbo denominativo deriva de la palabra para ''cabello'' y significa erizarse o estremecerse de horror—literalmente, que se ericen los pelos por terror. Jeremías 2:12 llama a los cielos a ''estremecerse'' de horror ante la apostasía de Israel (paralelo a ''espantaos y horrorizaos''). Ezequiel lo usa dos veces en oráculos de juicio: los reyes ''se estremecerán'' ante la caída de Tiro (27:35) y las naciones ''temblarán'' ante la espada blandida contra Egipto (32:10). El verbo captura la reacción visceral y física a la catástrofe—el temblor involuntario y el terror que eriza el cabello que acompaña presenciar el juicio. Los contextos uniformemente involucran castigo divino dramático que horroriza a los observadores.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H8175b', 'spa', 'Arrebatar, lanzar como tempestad; arrastrar con viento violento o torbellino, literal o como juicio divino', 'Este verbo describe la acción violenta de arrebatar o arremolinar propia de los vientos tempestuosos. El Salmo 58:9 lo emplea para describir cómo Dios barre a los impíos «antes de que vuestras ollas sientan las espinas», imagen vívida de remoción súbita. El Salmo 50:3 describe la llegada de Dios: «a su alrededor hay gran tempestad». Job 27:21 presenta al viento del este arrebatando al malvado de su lugar. Daniel 11:40 lo usa para un rey que «se lanzará como tempestad» contra su enemigo. Es la fuerza abrumadora del viento como instrumento de juicio o guerra, que arrastra todo a su paso como un tornado sobre el paisaje.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H8177', 'spa', 'cabello (cognado arameo, de la cabeza)', 'Este sustantivo arameo significa ''cabello'', específicamente cabello de la cabeza, apareciendo tres veces en las visiones y narrativas de Daniel. Daniel 3:27 reporta que el fuego no chamuscó ''el cabello de sus cabezas'' cuando los tres hombres sobrevivieron el horno. Daniel 4:30 describe a Nabucodonosor durante su locura cuando ''su cabello creció como plumas de águilas'' (viviendo como una bestia). Daniel 7:9 en la visión del Anciano de Días ve a uno ''cuyo cabello era como lana pura''—blanco y venerable. El término es el equivalente arameo estándar al hebreo se''ar, usado literalmente para cabello humano (o angelical) de la cabeza.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H8178a', 'spa', 'horror, estremecimiento (reacción temblorosa a catástrofe)', 'Este sustantivo denota el sentimiento o estado de horror y estremecimiento—la reacción visceral a presenciar juicio o desastre. Aparece como acusativo cognado con el verbo ''estremecerse'' en dos oráculos de Ezequiel (27:35; 32:10), intensificando la expresión: ''se estremecieron con estremecimiento''. Job 18:20 describe cómo las generaciones futuras ''se apoderaron del estremecimiento'' ante el destino del impío (paralelo a ''se espantaron''). La palabra captura no solo miedo sino temblor físico—la respuesta involuntaria del cuerpo al horror. El campo semántico se superpone con terror, pavor y el temblor que acompaña presenciar el juicio divino.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H8179', 'spa', 'Puerta o entrada de ciudad, templo o palacio; por metonimia, comunidad o jurisdicción territorial (''dentro de tus puertas'')', 'שַׁעַר designa en primer lugar la puerta física — la abertura arquitectónica en la muralla de una ciudad, el recinto del templo o el complejo palaciego por la que transita la gente, que se cierra de noche y se abre al amanecer. Las puertas eran también el centro cívico donde se sentaban los ancianos, se administraba justicia y se realizaban los asuntos públicos. En la legislación deuteronómica surge un uso metonímico distintivo: ''dentro de tus puertas'' equivale a ''dentro de tus ciudades'' o ''en tus poblaciones'', donde la puerta representa toda la comunidad bajo su jurisdicción. El español puerta, el francés porte y el alemán Tor traducen consistentemente el sentido físico, mientras que la construcción posesiva ''tus puertas'' señala la extensión territorial.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H8181', 'spa', 'Cabello, pelo — vello corporal o cabello de la cabeza, prominente en el diagnóstico de pureza, los votos nazareos y las descripciones físicas', 'Cabello, pelo — vello corporal o cabello de la cabeza, prominente en el diagnóstico de pureza, los votos nazareos y las descripciones físicas');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H8184', 'spa', 'Cebada — el cereal con aristas, una de las siete especies de la Tierra, usado como alimento, forraje y ofrenda', 'Cebada — el cereal con aristas, una de las siete especies de la Tierra, usado como alimento, forraje y ofrenda');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H8185', 'spa', 'cabello, un cabello — un solo cabello o, colectivamente, el cabello de la cabeza o el vello del cuerpo', 'Sa''arah es el sustantivo unitario derivado de se''ar (''cabello''), formado con la terminación femenina para designar un solo mechón o hebra. Aparece en expresiones memorables de precisión y cuidado divino: los honderos de Benjamín podían lanzar piedras sin errar por el ancho de un cabello (Jue 20:16), y ni un cabello de la cabeza de Jonatán caería a tierra (1 Sam 14:45). La misma garantía se extiende al hijo de la mujer sabia de Tecoa (2 Sam 14:11) y a Adonías (1 Re 1:52). En Job 4:15 adquiere un sentido colectivo estremecedor cuando el vello de la carne de Elifaz se eriza.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H8186b', 'spa', 'cosa horrible, abominación (acto moralmente escandaloso)', 'Este sustantivo femenino denota algo horrible o abominable, un acto tan moralmente escandaloso que provoca repulsión. Jeremías 18:13 pregunta retóricamente quién ha oído tal cosa: ''la virgen Israel ha hecho una cosa horrible''—abandonó a su Dios por ídolos. Oseas 6:10 declara ''he visto una cosa horrible en la casa de Israel''—su prostitución y contaminación. La variación Ketiv-Qere en Oseas sugiere cierta incertidumbre textual sobre la forma exacta, pero el sentido permanece claro: algo moralmente repugnante que viola las expectativas del pacto. El término conlleva mayor peso moral que una simple ''cosa mala''—es un ultraje, una abominación contra las normas divinas.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H8189', 'spa', 'Saaraim (nombre de lugar: ''puertas dobles,'' dos ubicaciones en Judá/Simeón)', 'Saaraim significa ''dos puertas'' o ''puertas dobles,'' designando dos pueblos distintos en el sur de Israel. El primero aparece en la Sefela de Judá (Josué 15:36) y a lo largo de la ruta de huida de los filisteos después de que David matara a Goliat (1 Samuel 17:52, donde la Septuaginta lo traduce como ''las puertas''). El segundo pertenecía a Simeón en el Néguev (1 Crónicas 4:31), aparentemente el mismo que Saruén (Josué 19:6) y posiblemente Silhim (Josué 15:32). El nombre probablemente refleja una característica arquitectónica real—pueblos con sistemas de puertas dobles. La doble atestación crea ambigüedad geográfica que debe resolverse por contexto.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H8191', 'spa', 'Deleite, placer exquisito; sustantivo plural intensivo que expresa gozo profundo, dirigido frecuentemente a la ley o sabiduría de Dios.', 'Sustantivo plural intensivo que expresa un deleite profundo y un gozo supremo, usado de manera más característica en el Salmo 119 para describir el amor apasionado del salmista por la Torá de Dios. Cinco de sus nueve apariciones se encuentran en ese único salmo (119:24, 77, 92, 143, 174), donde la ley es descrita como el deleite del hablante en tiempos de aflicción y destierro. En Proverbios 8:30-31, la Sabiduría personificada declara que era el deleite cotidiano de Dios en la creación, regocijándose en el mundo habitado. Isaías 5:7 llama a Judá ''la plantación de su deleite'', y Jeremías 31:20 nombra a Efraín ''hijo de delicias''.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H8193', 'spa', 'Labio(s), habla; borde u orilla de un objeto; ribera de aguas; también lengua o idioma', 'שָׂפָה es una de las metáforas corporales más elegantes del hebreo: irradia desde el labio físico para abarcar el habla, el borde de cualquier superficie, la orilla de cualquier masa de agua e incluso el idioma humano. Como órgano del habla aparece más de 120 veces — labios que guardan, labios mentirosos, labios aduladores, labios ardientes tocados por una brasa (Is 6:7). Pero la misma palabra designa el borde del gran mar de bronce de Salomón (1 R 7:23), la orilla de las cortinas del tabernáculo (Éx 26:4) y la ribera del mar donde los descendientes de Abraham serán tan numerosos como la arena (Gn 22:17). De modo aún más notable, שָׂפָה significa ''lengua, idioma'' en el relato de Babel: ''toda la tierra tenía un solo labio'' (Gn 11:1).');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H8198', 'spa', 'שִׁפְחָה — sierva, esclava; también autodesignación humilde de una mujer al dirigirse a un superior. Sustantivo femenino que designa a una criada o es', 'שִׁפְחָה — sierva, esclava; también autodesignación humilde de una mujer al dirigirse a un superior. Sustantivo femenino que designa a una criada o esclava dentro de un hogar, sinónimo de אָמָה (H0519) aunque con matices sociales sutiles. Aparece por primera vez en Gn 12:16 entre los regalos del faraón a Abram y cobra protagonismo en las narrativas matriarcales: Agar es la שִׁפְחָה de Sara (Gn 16:1), Bilhá y Zilpá son las שְׁפָחוֹת que engendran hijos en nombre de Raquel y Lea (Gn 30:4-12). Más allá de la servidumbre real, la palabra funciona como expresión convencional de humildad cuando una mujer se dirige a un superior social, como hace Ana ante Elí (1 S 1:16) y Abigail ante David (1 S 25:24-28).');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H8199', 'spa', 'Juzgar, gobernar, vindicar, litigar; como participio: juez (cargo); Nifal: ser juzgado, comparecer en juicio', 'שָׁפַט es el verbo jurídico y gubernamental de la Biblia hebrea, cubriendo el arco completo desde la adjudicación en el tribunal hasta la gobernanza nacional y la vindicación divina de los oprimidos. En el periodo de los Jueces, el שׁוֹפֵט no era un simple árbitro sino un líder carismático militar y político, acepción que el árabe قَضَى (que abarca tanto ''juzgar'' como ''gobernar'') confirma. El mismo verbo se vuelve adversarial en el Nifal para significar ''entrar en juicio'', como cuando Dios desafía a Israel a contender con Él (Is 43:26). El español distingue juzgar (adjudicar) de gobernar y vindicar, reflejando las mismas fracturas visibles en la evidencia hebrea.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H8201', 'spa', 'Juicios, actos de justicia divina — actos punitivos ejecutados por Dios contra naciones o contra los impíos. Sustantivo masculino usado exclusivamente', 'Juicios, actos de justicia divina — actos punitivos ejecutados por Dios contra naciones o contra los impíos. Sustantivo masculino usado exclusivamente en plural (שְׁפָטִים) para designar los actos punitivos de justicia de Dios, distinto del más común מִשְׁפָּט. Aparece primero en la narrativa del Éxodo, donde Dios promete sacar a Israel de Egipto ''con grandes actos de juicio'' (Éx 6:6; 7:4) y ejecuta juicios contra todos los dioses de Egipto (Éx 12:12; Nm 33:4). Ezequiel domina su uso, empleando la frase ''ejecutar juicios'' (עָשָׂה שְׁפָטִים) repetidamente para anunciar castigo divino contra Jerusalén y las naciones (Ez 5:10, 15; 11:9; 16:41; 25:11; 28:22, 26; 30:14, 19). Ezequiel 14:21 nombra los cuatro juicios de Dios: espada, hambre, fieras y pestilencia. Proverbios 19:29 extiende el término a las consecuencias judiciales que esperan al burlador.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H8202', 'spa', 'Safat: nombre propio masculino que significa ''él ha juzgado'', llevado por al menos cinco hombres, incluido el padre del profeta Eliseo', 'Nombre propio masculino que significa ''él ha juzgado'', derivado de la raíz שָׁפַט (juzgar). Su portador más destacado es Safat hijo de Adlai, padre del profeta Eliseo, quien aparece repetidamente en el ciclo de Elías y Eliseo (1 Re 19:16, 19; 2 Re 3:11; 6:31). Otros portadores incluyen un espía simeonita enviado a explorar Canaán (Nm 13:5), un nieto de Zorobabel en la genealogía davídica (1 Cr 3:22), un jefe gadita (1 Cr 5:12) y un pastor de David encargado del ganado en los valles (1 Cr 27:29). La Septuaginta lo traduce consistentemente como Σαφατ.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H8203', 'spa', 'Sefatías — nombre propio masculino que significa ''YHWH ha juzgado'', llevado por varios personajes del AT, entre ellos un hijo de David. Es un nombre t', 'Sefatías — nombre propio masculino que significa ''YHWH ha juzgado'', llevado por varios personajes del AT, entre ellos un hijo de David. Es un nombre teofórico que combina la raíz del verbo ''juzgar'' con el nombre divino, significando ''YHWH ha juzgado'' o ''YHWH ha vindicado''. Lo llevan al menos ocho individuos distintos en la Biblia hebrea: el quinto hijo de David (2 Sam 3:4; 1 Cr 3:3), un líder benjaminita (1 Cr 9:8), uno de los guerreros de David en Siclag (1 Cr 12:5), un príncipe simeonita (1 Cr 27:16), jefes de familias que regresaron del exilio (Esd 2:4; 8:8; Neh 7:9), y uno de los acusadores de Jeremías (Jer 38:1). La forma griega de la LXX Saphatias y las diversas formas multilingües transliteran el mismo nombre hebreo subyacente.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H8205', 'spa', 'Altura pelada y desprovista de árboles — terreno elevado y expuesto, usado frecuentemente para paisajes desolados en la imaginería profética.', 'Este sustantivo designa una altura pelada y azotada por el viento, desprovista de vegetación: una cima o cresta expuesta. Los profetas, especialmente Jeremías, lo emplean repetidamente para evocar desolación espiritual: la adoración idolátrica de Israel en las ''alturas peladas'' (Jer 3:2, 21; 7:29) y el viento abrasador del desierto que barre sobre ellas (Jer 4:11; 12:12; 14:6). Sin embargo, la palabra también porta notas de esperanza, como cuando Isaías vislumbra a Dios convirtiendo las alturas desnudas en manantiales de agua (Is 41:18; 49:9). El puesto de Balaam en Números 23:3 es igualmente una altura pelada, elegida por su vista sin obstrucciones.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H8206', 'spa', 'Sufim (nombre personal: antepasado benjaminita y portero del templo)', 'Sufim es un nombre personal que aparece en genealogías benjaminitas y listas de servicio levítico. El nombre muestra variación ortográfica (Sufim, Sufam, Sefufam) entre los textos, típico de registros genealógicos. 1 Crónicas 7:12 y 7:15 enumeran a Sufim en complejos árboles familiares benjaminita-manasitas que los eruditos encuentran difíciles de armonizar. 1 Crónicas 26:16 nombra a Sufim como portero del templo asignado a la puerta occidental Salequet y la calzada superior. Las versiones griegas reflejan la complejidad textual con transliteraciones variadas. El nombre puede estar relacionado con una raíz que significa ''serpiente'' pero esto permanece incierto.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H8210', 'spa', 'Derramar, verter o derramar sangre; cubre la libación ritual, el derramamiento de sangre, la efusión de ira o espíritu, y la disolución reflexiva', 'שָׁפַךְ es el verbo hebreo del derramamiento irreversible: una vez que el líquido sale del recipiente, no puede recogerse. Esta finalidad física confiere a la palabra su devastador peso moral en la expresión שָׁפַךְ דָּם (''derramar sangre''), el modismo bíblico primario para el homicidio. La misma raíz que describe a un levita vertiendo sangre sacrificial al pie del altar (Lv 4:7) también incrimina a los asesinos que ''derraman sangre inocente'' (Dt 19:10; Is 59:7). El cognado árabe سَفَكَ conserva la misma especialización en derramamiento de sangre. En los profetas, Dios ''derrama'' su ira como fuego líquido, y en Lamentaciones el alma del poeta ''se derrama'' en dolor — el Hitpael reflexivo capturando la disolución desde el interior.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H8213', 'spa', 'Estar bajo o ser humillado; abatir, rebajar o humillarse ante Dios o ante otros', 'Estar bajo o ser humillado; abatir, rebajar o humillarse ante Dios o ante otros');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H8214', 'spa', 'Humillar, abatir (arameo); rebajar o derribar a alguien en autoridad u orgullo, especialmente en contextos reales de Daniel', 'Este verbo arameo significa humillar o abatir, y aparece exclusivamente en Daniel en contextos de humillacion real. Daniel 4:37 habla de Dios que «puede humillar a los que andan con soberbia». Daniel 5:19 describe como Nabucodonosor «derribaba a quien queria» cuando tenia poder. Daniel 5:22 reprende a Belsasar: «no has humillado tu corazon» a pesar de saber lo que le sucedio a Nabucodonosor. Daniel 7:24 profetiza sobre un rey que «derribara a tres reyes». En la teologia de Daniel, el orgullo humano inevitablemente se encuentra con la humillacion divina: el Altisimo derriba al soberbio y exalta al humilde.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H8217', 'spa', 'Bajo de posición (físicamente); bajo de estatus o estima (socialmente); humilde o modesto de espíritu (moralmente positivo). El adjetivo שָׁפָל traza ', 'Bajo de posición (físicamente); bajo de estatus o estima (socialmente); humilde o modesto de espíritu (moralmente positivo). El adjetivo שָׁפָל traza un arco semántico desde el suelo hasta el alma. En su sentido más concreto, describe cosas que están físicamente bajas: una vid que se extiende cerca de la tierra (Ez 17:6), una lesión cutánea hundida respecto a la piel circundante (Lv 13:20-26), o el sonido del molino que se apaga (Ecl 12:4). De ahí asciende a la descripción social: un reino mantenido deliberadamente ''bajo'' para que no pueda rebelarse (Ez 17:14; 29:14-15), un rey humillado ''ante sus propios ojos'' (2 Sam 6:22). Pero su clímax teológico llega en Isaías 57:15, donde Dios declara que habita ''con el de espíritu humilde y contrito'', transformando שָׁפָל de depresión física en virtud espiritual.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H8219', 'spa', 'La Sefela — la región baja de colinas entre las tierras altas de Judá y la llanura costera del Mediterráneo. Término geográfico que designa la Sefela,', 'La Sefela — la región baja de colinas entre las tierras altas de Judá y la llanura costera del Mediterráneo. Término geográfico que designa la Sefela, la franja de colinas onduladas que se extiende entre la cordillera central de Judá y la llanura costera filistea. Casi todas las ocurrencias llevan el artículo definido, marcándola como una zona topográfica bien conocida y no como una descripción genérica. Los escritores bíblicos distinguen consistentemente la Sefela de la montaña (הָהָר), el Néguev y la Arabá, tratándola como su propia zona ecológica y militar, famosa por sus bosques de sicómoros (1 R 10:27) y sus ciudades fronterizas disputadas.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H8222', 'spa', 'Bigote, labio superior; el vello facial sobre la boca, frecuentemente cubierto en señal de duelo o vergüenza', 'Este sustantivo hebreo se refiere específicamente al bigote o la zona del labio superior. En la cultura israelita antigua, cubrirse el bigote era un gesto reconocido de duelo, vergüenza o impureza ritual: los leprosos debían cubrirlo (Lev 13:45), los profetas predicen una vergüenza tan profunda que los hombres se cubrirán los labios (Miq 3:7), y Ezequiel da instrucciones sobre costumbres de luto (Ez 24:17, 22). Que Mefiboset no se recortara el bigote (2 Sam 19:24) era señal de duelo por el rey. La evidencia multilingüe converge: en español ''bigote'', en inglés ''mustache'', en francés ''moustache'' y el cognado siríaco confirman el referente anatómico específico.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H8227a', 'spa', 'Daman, hyrax; pequeño mamifero (hyrax syriacus) que habita entre las rocas, clasificado como inmundo en la ley levitica', 'Este sustantivo designa al daman o hyrax, un pequeño mamifero peludo que vive en terreno rocoso. Levitico 11:5 y Deuteronomio 14:7 lo clasifican como inmundo porque parece rumiar pero no tiene pezuñas hendidas (aunque en realidad el hyrax no rumia verdaderamente; la clasificacion se basa en el comportamiento observable). Salmo 104:18 celebra poeticamente que «las peñas son refugio para los damanes». Proverbios 30:26 elogia a los damanes como «pueblo sin fuerza, que hacen sus casas en las rocas». Estas criaturas ejemplifican la sabiduria al elegir su habitat: debiles pero protegidos al habitar en grietas rocosas inaccesibles.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H8227b', 'spa', 'Safán — escriba real bajo Josías que leyó el Libro de la Ley descubierto; patriarca de una familia prominente', 'Safán — escriba real bajo Josías que leyó el Libro de la Ley descubierto; patriarca de una familia prominente');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H8229', 'spa', 'Abundancia, torrente, multitud; compañía o tropa de personas.', 'El sustantivo שִׁפְעָה denota una gran cantidad o masa, ya sea de cosas o de personas. Aplicado a fuerzas naturales, significa un torrente o abundancia abrumadora: las ''aguas torrenciales'' de Job (22:11; 38:34), la ''abundancia de camellos'' que cubre Madián (Isa 60:6) y la ''multitud de caballos'' que sacude las murallas de Tiro (Ezeq 26:10). Pero en 2 Reyes 9:17, cuando el centinela divisa la fuerza de Jehú acercándose, la palabra se desplaza para significar una compañía o tropa de hombres, una banda militar en vez de una masa indiferenciada. El español distingue con nitidez ''multitud de'' (para cosas) de ''tropa'' (para soldados), confirmando los dos sentidos.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H8232', 'spa', 'ser agradable, parecer bien, ser aceptable (arameo)', 'Este verbo arameo significa ser justo, agradable o aceptable para alguien. Aparece en textos del período persa describiendo aprobación real o consejo bien recibido. Daniel 4:2 y 6:1 usan la forma perfecta con la preposición ''delante de'' (qodam): ''pareció bien delante de'' el rey hacer algo—el rey se complació en tomar cierta acción. Daniel 4:27 cambia al imperfecto: ''te sea aceptable mi consejo''—que el rey encuentre agradable el consejo de Daniel. El verbo funciona en contextos cortesanos de toma de decisiones y consejo real, indicando aprobación subjetiva o recepción favorable.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H8239', 'spa', 'Poner (una olla al fuego), colocar, asentar; por extensión, ordenar o establecer', 'Verbo denominativo que significa poner algo en su lugar, especialmente una olla de cocción sobre el fuego. Eliseo ordena ''pon la olla'' (2 Re 4:38), y Ezequiel emplea la misma imagen simbólicamente (Ez 24:3). El campo semántico se extiende desde este acto doméstico concreto hasta Dios colocando a alguien en el polvo de la muerte (Sal 22:15) y ordenando la paz (Isa 26:12). El español ''pon'' y el francés ''mettre/plaça-sur'' confirman el significado central de colocación deliberada, mientras que los usos teológicos revelan a un Dios que dispone tanto el juicio como el shalom.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H8242', 'spa', 'Cilicio usado en duelo o penitencia; también un costal o saco tosco para transportar grano. Tela basta y oscura —generalmente tejida de pelo de cabra—', 'Cilicio usado en duelo o penitencia; también un costal o saco tosco para transportar grano. Tela basta y oscura —generalmente tejida de pelo de cabra— que cumplía dos funciones distintas en el mundo antiguo. Con mayor frecuencia aparece como vestidura de luto y arrepentimiento: Jacob rasga sus ropas y se viste de שַׂק cuando cree que José ha muerto (Gn 37:34), los reyes se ciñen cilicio en crisis nacionales (1 R 20:31-32), y los profetas llaman a Israel a ''vestir cilicio y revolcarse en ceniza'' (Jer 48:37). Con menos frecuencia, la misma palabra designa el costal utilitario para granos, como en la narrativa de José, donde la plata de los hermanos se esconde en sus שַׂקִּים (Gn 42:25-35).');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H8245', 'spa', 'Velar, vigilar, estar despierto; de Dios velando sobre su palabra o su pueblo; también acechar con intención hostil', 'Verbo de vigilia intensa y decidida que abarca desde la fidelidad divina hasta la amenaza depredadora. Su aparición más célebre es Jeremías 1:12, donde Dios declara «Yo velo sobre mi palabra para cumplirla», un pasaje enriquecido por el juego de palabras con shaqed (almendro), el «vigilante» que florece primero en primavera. La misma raíz describe el insomnio en el Salmo 102:7, donde el salmista permanece despierto «como ave solitaria sobre el tejado». En su faceta más oscura, el vocablo describe a un leopardo que «acecha» contra las ciudades para atrapar a su presa (Jer 5:6).');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H8246', 'spa', 'En forma de almendra; participio Pual de שָׁקַד usado para las copas labradas como flores de almendro en la menorá.', 'Este participio Pual deriva de la raíz שָׁקַד (''almendro'') y aparece exclusivamente en los textos de construcción del tabernáculo en Éxodo 25 y 37. Describe las copas decorativas del candelabro de oro (menorá) que estaban labradas en forma de flores de almendro. El almendro tenía un significado especial en la cultura israelita por ser el primer árbol en florecer en primavera, simbolizando vigilancia, un juego de palabras que los profetas explotan en otros pasajes (Jer 1:11-12). El español ''en forma de almendra'' y el francés amande-façonné confirman la referencia botánica uniforme en las seis apariciones.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H8247', 'spa', 'Almendro o almendra; el arbol apreciado por su temprana floracion, o sus frutos comestibles, con uso literal y simbolico', 'Este sustantivo designa tanto la almendra como el almendro. Genesis 43:11 incluye almendras entre los productos selectos que Jacob envia a Egipto. Numeros 17:8 describe la vara de Aaron que brotó y produjo almendras de la noche a la mañana, como señal de eleccion divina. Eclesiastes 12:5 emplea la floracion del almendro como parte de una alegoria sobre la vejez. Jeremias 1:11 contiene un juego de palabras: Dios muestra a Jeremias una rama de almendro (shaqed) y dice «yo estoy velando» (shoqed), explotando la similitud fonetica. La temprana floracion primaveral del almendro lo convirtio en simbolo de vigilancia y vida nueva.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H8248', 'spa', 'Dar de beber, abrevar o regar; causativo Hifil de beber: proporcionar agua a personas, animales o tierras. שָׁקָה en su forma Hifil es el verbo estánd', 'Dar de beber, abrevar o regar; causativo Hifil de beber: proporcionar agua a personas, animales o tierras. שָׁקָה en su forma Hifil es el verbo estándar de la Biblia para dar de beber a alguien o algo, una acción aparentemente sencilla que carga un enorme peso narrativo. Rebeca abreva los camellos del siervo de Abraham, desencadenando la narrativa matrimonial patriarcal (Gn 24:14-46). Moisés golpea la roca para ''darles de beber'' (Nm 20:8). La evidencia multilingüe revela una división constante: cuando el objeto es un ser vivo, las lenguas usan vocabulario de ''dar de beber'' (español dar de beber), pero cuando el objeto es la tierra, cambian a palabras de riego (español regar), una frontera semántica genuina incorporada en el verbo.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H8251', 'spa', 'Cosa detestable o abominación; un ídolo, práctica idolátrica o inmundicia contaminante aborrecible ante Dios', 'Cosa detestable o abominación; un ídolo, práctica idolátrica o inmundicia contaminante aborrecible ante Dios');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H8252', 'spa', 'Estar quieto, en reposo, sin perturbación; de tierras en paz tras la guerra, de personas en tranquilidad; causativamente, dar descanso o calmar', 'Estar quieto, en reposo, sin perturbación; de tierras en paz tras la guerra, de personas en tranquilidad; causativamente, dar descanso o calmar');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H8254', 'spa', 'Pesar plata como forma de pago; sopesar o evaluar el valor; ser pesado (pasivo)', 'Pesar plata como forma de pago; sopesar o evaluar el valor; ser pesado (pasivo)');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H8255', 'spa', 'Siclo; unidad estándar de peso (~11,4 g) utilizada como medida principal de valor y moneda. El שֶׁקֶל es la unidad fundamental de peso y valor monetar', 'Siclo; unidad estándar de peso (~11,4 g) utilizada como medida principal de valor y moneda. El שֶׁקֶל es la unidad fundamental de peso y valor monetario del antiguo Israel. Derivado de la raíz que significa ''pesar'', originalmente denotaba una masa específica de plata u oro colocada en una balanza, no una moneda acuñada. Fija el precio de la compensación por un esclavo corneado por un buey (Éx 21:32), mide el oro del tabernáculo (Éx 38:24) y establece las valoraciones del santuario (Lv 27). Amós condena a los mercaderes que reducen el siclo para estafar a los compradores (Am 8:5). Las traducciones en diversas lenguas —español ''siclo'', francés ''sicle'', alemán ''Schekel''— transliteran en lugar de traducir, reconociendo el siclo como un estándar culturalmente específico.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H8256', 'spa', 'sicómoro — el sicómoro o higuera silvestre (Ficus sycomorus), árbol de tierras bajas apreciado por su madera y fruto', 'Shiqmah designa el sicómoro o higuera-sicómoro (Ficus sycomorus), un árbol grande y frondoso que prosperaba en las tierras bajas cálidas de la Sefela. Era tan abundante que el cedro parecía un lujo en comparación: Salomón hizo que el cedro fuera ''tan común como los sicómoros en las tierras bajas'' (1 Re 10:27). El profeta Amós se identificó como ''cultivador de sicómoros'' (Am 7:14), labor que consistía en perforar el fruto para acelerar su maduración. Cuando Dios hirió los sicómoros con escarcha junto a las viñas (Sal 78:47), significó una devastación agrícola total.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H8257', 'spa', 'Hundirse, sumergirse, aplacarse; en Hiphil, hacer hundirse o asentar.', 'Un verbo que describe movimiento descendente hacia una superficie o medio: hundirse, aplacarse, extinguirse. En sus formas Qal y Nifal, retrata el fuego que se apaga (Núm 11:2) o la tierra que se hunde como la llanura aluvial del Nilo (Amós 8:8; 9:5). Jeremías lo emplea memorablemente para Babilonia hundiéndose como una piedra en el agua (Jer 51:64). El Hiphil causativo aparece cuando Dios aplaca las aguas de Egipto (Ezeq 32:14) y presiona la lengua del Leviatán (Job 41:1). El español ''hundirse'' y el inglés ''sink'' convergen en la imagen central, mientras el pasaje de Ezequiel extiende singularmente el sentido hacia ''asentarse'' o ''aclararse''.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H8259', 'spa', 'Mirar hacia abajo desde una altura, asomarse por una ventana o lugar elevado; dar hacia un lugar o dominarlo (topográfico)', 'Mirar hacia abajo desde una altura, asomarse por una ventana o lugar elevado; dar hacia un lugar o dominarlo (topográfico)');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H8262', 'spa', 'abominar, considerar detestable — verbo Piel que expresa repulsión ritual o el acto de hacerse abominable', 'Shiqqets es un denominativo Piel derivado de שֶׁקֶץ (''cosa detestable''), que expresa con fuerza el acto de considerar algo como completamente abominable. Aparece casi exclusivamente en contextos legales sobre alimentos puros e impuros: ''los abominaréis'' (Lv 11:11, 13) y ''no os hagáis abominables'' (Lv 11:43; 20:25). La construcción enfática con infinitivo absoluto en Deuteronomio 7:26 — שַׁקֵּץ תְּשַׁקְּצֶנּוּ, ''lo aborrecerás por completo'' — se empareja con el sinónimo תָּעַב para recalcar la intensidad de la respuesta que se exige a Israel frente a la idolatría.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H8263', 'spa', 'Cosa detestable o abominable, usada en las leyes dietéticas levíticas y en denuncias proféticas contra la idolatría', 'Sustantivo que expresa fuerte repulsión, designando criaturas y prácticas que resultan ritualmente aborrecibles ante Dios. Casi todas las apariciones se concentran en Levítico 11, el código dietético, donde las criaturas acuáticas sin aletas ni escamas, ciertas aves y los animales que se arrastran son declarados שֶׁקֶץ — no meramente impuros, sino activamente detestables (Lv 11:10-13, 20, 23, 41-42). La palabra también aparece en contextos más amplios de ofrendas alimenticias contaminadas (Lv 7:21) y de culto idolátrico (Ez 8:10). A diferencia del más general תּוֹעֵבָה (''abominación''), שֶׁקֶץ conlleva una cualidad casi visceral y física de repugnancia: el escalofrío que se siente ante algo inherentemente repulsivo.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H8264', 'spa', 'Precipitarse, correr con ímpetu, lanzarse; en sentido figurado, anhelar, desear con inquietud', 'Verbo que describe un movimiento enérgico y a menudo agresivo: precipitarse, embestir, correr de un lado a otro. En Joel 2:9 los ejércitos de langostas se precipitan por la ciudad; en Nahúm 2:4 los carros se lanzan desbocados por las calles. Proverbios 28:15 compara al gobernante malvado sobre un pueblo pobre con un oso que embiste. Pero esa misma energía inquieta se vuelve hacia adentro en Salmo 107:9 e Isaías 29:8, donde el alma se consume en un anhelo insatisfecho. La distinción en español entre ''correr'' para el sentido físico y ''anhelar'' para el metafórico refleja bien los dos polos de este vocablo.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H8266', 'spa', 'Obrar con falsedad, mentir; actuar con engaño o quebrantar la fe, usado para traición pactual y fidelidad divina', 'Derivado de שֶׁקֶר (''falsedad''), este verbo abarca todo el espectro del obrar engañoso, desde quebrantar juramentos solemnes hasta proferir mentiras abiertas. En Génesis 21:23 Abraham pide a Abimelec que jure no obrar con falsedad, mientras que en 1 Samuel 15:29 Samuel declara que la Gloria de Israel no mentirá, empleando la misma raíz para afirmar la constancia divina. El Piel intensifica la acción como engaño deliberado y sostenido. El Salmo 44:17 protesta conmovedoramente que Israel no ha sido infiel al pacto de Dios a pesar del sufrimiento.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H8267', 'spa', 'Falsedad, mentira o vanidad engañosa; el vocablo hebreo para la mentira, el fraude y todo lo que traiciona la confianza.', 'שֶׁקֶר es el término más incisivo del vocabulario bíblico para designar lo falso. Abarca la mentira deliberada (como en el noveno mandamiento, Éx 20:16), la conducta fraudulenta (Pr 11:18) y la vacuidad engañosa de aquello que promete mucho pero no cumple nada: un caballo cuya fuerza resulta vana en la batalla (Sal 33:17) o un encanto que al final decepciona (Pr 31:30). El campo semántico hebreo es más amplio que cualquier término aislado en otras lenguas, pues se extiende desde el perjurio en un tribunal hasta la futilidad cósmica de los ídolos (Jer 10:14).');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H8269', 'spa', 'Jefe, gobernante, príncipe, oficial, capitán; persona con autoridad o rango en la administración civil, militar o real.', 'שַׂר es el sustantivo más versátil de la Biblia hebrea para designar a quien ejerce autoridad delegada. Puede referirse a un caudillo tribal que guía a Israel por el desierto (Nm 21:18), a los cortesanos del faraón (Gn 12:15), a un capitán militar al mando de miles o cientos (Éx 18:21) o a un gobernador de provincia. En sus usos más exaltados, שַׂר alcanza la esfera angélica: ''Miguel, vuestro príncipe'' (Dn 10:21), mostrando cómo la misma raíz que describe al supervisor de un panadero en Génesis puede designar a un guardián cósmico en la visión apocalíptica.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H8271', 'spa', 'Verbo arameo: soltar, desatar, resolver (problemas); morar, habitar; comenzar, dar inicio', 'Verbo arameo con un campo semántico sorprendentemente amplio, rastreable en todos sus sentidos hasta la idea raíz de soltar o liberar. Literalmente, los tres varones en el horno son hallados ''sueltos'' de sus ataduras, caminando libremente en el fuego (Dan 3:25). En sentido figurado, el don de Daniel para ''desatar nudos'' —resolver enigmas intrincados— lo hace indispensable en la corte babilónica (Dan 5:12, 16). El sentido de ''morar'' probablemente deriva del acto del viajero de soltar las correas de carga al acampar (Dan 2:22). En Esdras 5:2 el Piel produce ''comenzaron'', quizá desde la idea de soltar las riendas para poner en marcha una empresa.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H8272', 'spa', 'Sarezer (nombre personal: origen asirio/babilonio, hijo y embajador)', 'Sarezer es un nombre personal de origen asirio o babilonio, posiblemente significando ''[dios] proteja al rey.'' Aparece en dos contextos distintos. 2 Reyes 19:37 e Isaías 37:38 (relatos paralelos) identifican a Sarezer como uno de los hijos de Senaquerib que asesinó a su padre en el templo de Nisroc y huyó a Ararat. Zacarías 7:2 menciona a un Sarezer enviado a Betel como parte de una delegación que preguntaba sobre el ayuno—probablemente un individuo diferente de una generación posterior. Las versiones griegas muestran la variación consonántica típica al transliterar nombres extranjeros.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H8274', 'spa', 'Serebías: levita que regresó del exilio babilónico con Esdras y sirvió en el culto público y la renovación del pacto', 'Nombre propio levítico que aparece exclusivamente en los libros postexílicos de Esdras y Nehemías. Serebías fue reclutado por Esdras junto al canal de Ahava como un levita capaz para el viaje de regreso a Jerusalén (Esd 8:18) y se le confiaron los utensilios del templo de oro y plata (Esd 8:24). Posteriormente sirvió como lector público e intérprete de la Torá (Neh 8:7), dirigió al pueblo en confesión y adoración comunitaria (Neh 9:4-5) y selló el pacto de fidelidad (Neh 10:12). Su nombre aparece en la lista de cantores y porteros levíticos (Neh 12:8, 24), subrayando su papel central en la vida espiritual de la comunidad restaurada.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H8275', 'spa', 'Cetro; vara real que simboliza autoridad, especificamente el cetro de oro del rey persa en Ester', 'Este sustantivo designa un cetro real y aparece exclusivamente en el libro de Ester para describir el cetro de oro del rey Asuero. Ester 4:11 explica que cualquiera que se acercase al rey sin ser convocado seria ejecutado, a menos que el rey extendiese el cetro de oro. Ester 5:2 describe dos veces como el rey extiende el cetro hacia Ester, concediendole audiencia. Ester 8:4 repite el gesto hacia ella. En la narrativa de Ester, el cetro se convierte en cuestion de vida o muerte: su extension significa favor y vida, su retencion significa muerte segura. Encarna la prerrogativa real de conceder audiencia o condenar.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H8278', 'spa', 'Tejido trenzado; vestiduras sacerdotales especialmente tejidas o trenzadas para el servicio del tabernaculo', 'Este sustantivo aparece unicamente en Exodo dentro del material sacerdotal, y designa vestiduras especiales tejidas o trenzadas para el servicio del tabernaculo. Siempre aparece en la frase «las vestiduras tejidas para ministrar en el lugar santo» o similar (Exodo 31:10, 35:19, 39:1, 41). La naturaleza exacta de este tejido es incierta: algunas traducciones entienden «vestiduras finamente tejidas», otras «obra trenzada». La Septuaginta lo traduce como «vestiduras liturgicas». Estas prendas eran distintas de la ropa sacerdotal ordinaria, elaboradas con especial esmero para el servicio sagrado, con su tejido mismo confeccionado intencionalmente para el ministerio en la presencia de Dios.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H8282', 'spa', 'princesa, mujer noble; mujer de rango real o aristocrático', 'Forma femenina de שַׂר (príncipe/gobernante), designa a mujeres de estirpe real o noble. Las setecientas esposas-princesas de Salomón (1 Re 11:3) y las damas que acompañan a la madre de Sísara (Jue 5:29) ilustran la nobleza en sentido literal, mientras que Isaías vislumbra a reinas extranjeras amamantando a los hijos de Israel (Is 49:23). En Lamentaciones 1:1 la propia Jerusalén, otrora «señora entre las provincias», yace desolada. Las cinco ocurrencias apuntan de modo uniforme a mujeres de alto rango y autoridad.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H8283', 'spa', 'Sara — esposa de Abraham y madre de Isaac, la matriarca cuyo nombre significa ''princesa''', 'Sara — esposa de Abraham y madre de Isaac, la matriarca cuyo nombre significa ''princesa''');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H8286', 'spa', 'Serug; descendiente de Peleg y antepasado de Abraham en la genealogía patriarcal', 'Serug es un nombre propio dentro de la genealogía que conecta a Sem con Abraham. Aparece como hijo de Reu y padre de Nacor en Génesis 11:20-23, y nuevamente en el linaje resumido del Cronista (1 Cr 1:26). El nombre posiblemente derive de una raíz que significa «rama» o «sarmiento», y la LXX lo transcribe como Serouch. Todas las tradiciones textuales, tanto antiguas como modernas, mantienen la forma «Serug», lo que evidencia una transmisión estable del nombre a través de los siglos.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H8289', 'spa', 'Sarón — la fértil llanura costera del Mediterráneo, célebre por su belleza y pastizales', 'Sarón designa la amplia y fértil llanura que se extiende a lo largo de la costa mediterránea de Israel, aproximadamente desde Jope hacia el norte hasta el monte Carmelo. Renombrada por su exuberante vegetación, aparece en la poesía profética como símbolo de esplendor natural: «la gloria del Carmelo y de Sarón» (Is 35:2) y «Sarón será lugar de pastoreo para los rebaños» (Is 65:10). Su devastación se convierte en imagen del juicio divino: «Sarón es como un desierto» (Is 33:9). La «rosa de Sarón» en Cantares 2:1 se ha convertido en una de las imágenes botánicas más célebres de toda la Escritura.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H8292', 'spa', 'silbido, siseo (señal para rebaños o sonido de desprecio)', 'Este sustantivo femenino plural denota sonidos de silbido o siseo, apareciendo en dos contextos contrastantes. Jueces 5:16 lo usa para los ''silbidos'' o ''trinos'' para los rebaños—señales de pastores para guiar las ovejas (quizás explicando por qué Rubén se quedó entre los rediles en lugar de pelear). Jeremías 18:16 lo emplea para sonidos de desprecio: Jerusalén se convertirá en desolación y ''siseo'' (la variación Ketiv-Qere sugiere incertidumbre textual). La palabra puede describir tanto una señal funcional (silbar a los animales) como un sonido de desprecio (sisear ante las ruinas), con el contexto determinando el sentido.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H8294', 'spa', 'Sera (nombre personal: hija de Aser)', 'Sera fue la hija de Aser y la única mujer listada entre quienes descendieron a Egipto con Jacob (Génesis 46:17). Aparece en el censo del desierto como todavía viviendo entre los clanes de Aser (Números 26:46), y nuevamente en la genealogía de Crónicas (1 Crónicas 7:30). Su inclusión es notable dado el enfoque patriarcal de estas listas. La tradición judía posterior elaboró su historia extensamente, haciéndola inmortal y un vínculo entre generaciones. El nombre puede relacionarse con paralelos sabeos encontrados en inscripciones del sur de Arabia. Las versiones griegas muestran variación estándar al representar el nombre.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H8295', 'spa', 'hacer incisiones, arañar, cortar (hacer marcas en la piel)', 'Este verbo significa hacer incisiones, arañazos o cortes, típicamente en la piel. Levítico 21:5 lo usa al prohibir a los sacerdotes hacer ''cortes'' (incisiones) en su carne como ritos de luto—prácticas paganas típicas prohibidas al clero israelita. Zacarías 12:3 cambia a uso metafórico: quienes se carguen con la piedra de Jerusalén ''serán gravemente arañados/lacerados''—heridos por el intento. La raíz se relaciona con palabras arameas y acadias para cortar, rasgar o marcar. Las formas Qal y Nifal ambas aparecen, con el Nifal en Zacarías enfatizando la recepción pasiva de la herida.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H8297', 'spa', 'Sarai; nombre original de la esposa de Abraham antes de que Dios la renombrara Sara (''princesa''). El nombre Sarai designa a la esposa de Abraham en lo', 'Sarai; nombre original de la esposa de Abraham antes de que Dios la renombrara Sara (''princesa''). El nombre Sarai designa a la esposa de Abraham en los capítulos iniciales de su historia, antes de que Dios lo cambie a Sara en Génesis 17:15 como parte de la promesa del pacto de que ella daría a luz un hijo y sería madre de naciones. Las diecisiete ocurrencias se concentran en Génesis 11-17, trazando su recorrido desde Ur (11:29-31), pasando por la estancia en Egipto (12:11, 17), la tensión con Agar (16:1-8), y finalmente el momento del cambio de nombre. La Septuaginta lo traduce como Sara en todo momento, mientras que la Vulgata preserva la distinción entre Sarai y Sara.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H8299', 'spa', 'sarmientos, ramas (brotes de vid o higuera)', 'Este sustantivo masculino plural denota los sarmientos o ramas de vides e higueras—los brotes flexibles que portan el fruto. Génesis 40:10 y 40:12 lo usan en el sueño del copero de Faraón donde ve una vid con tres ''ramas'' brotando y floreciendo, luego produciendo uvas. Joel 1:7 lamenta la devastación de langostas que dejaron ''las ramas'' de la higuera blancas. La raíz se relaciona con entrelazar o trenzar (cognado a términos árabes para hojas de palma trenzadas), capturando el carácter entrelazado de las ramas de vid. El término enfatiza las partes productivas que portan fruto de la planta en lugar del tronco principal.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H8300', 'spa', 'Sobreviviente, el que queda: persona que permanece con vida tras una derrota militar, un desastre o un juicio divino', 'Sobreviviente, el que queda: persona que permanece con vida tras una derrota militar, un desastre o un juicio divino');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H8302b', 'spa', 'Coraza, cota de malla — armadura corporal de escamas o eslabones metálicos para proteger el torso en batalla', 'Se refiere a la armadura protectora que cubría el torso de un guerrero, típicamente construida con escamas metálicas superpuestas o placas eslabonadas. La palabra aparece por primera vez en la vívida descripción del equipo de Goliat: su cota de malla pesaba cinco mil siclos de bronce y estaba hecha de placas en forma de escamas (1 S 17:5). Saúl intentó vestir a David con una armadura similar antes del famoso duelo (1 S 17:38). En 1 R 22:34, una flecha penetra fatalmente «entre las junturas de la armadura», revelando los puntos vulnerables de la prenda. Isaías 59:17 aplica la imagen metafóricamente, describiendo a Dios vistiéndose de justicia como coraza.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H8304', 'spa', 'Seraías — nombre propio portado por sacerdotes, oficiales militares, escribas y jefes de clan a lo largo del AT. Un nombre propio que significa algo a', 'Seraías — nombre propio portado por sacerdotes, oficiales militares, escribas y jefes de clan a lo largo del AT. Un nombre propio que significa algo así como ''Yah persiste'' o ''Yah contende'', llevado por al menos diez individuos distintos en la Biblia hebrea. El más prominente es el sumo sacerdote ejecutado por Nabucodonosor en Ribla tras la caída de Jerusalén (2 R 25:18; Jer 52:24). Otro es el secretario real de David, cuyo nombre aparece con variantes ortográficas en los relatos paralelos — Seva, Savsa, Sisa — lo que sugiere dificultades en la transmisión escribal. El nombre también aparece en genealogías postexílicas vinculadas a Esdras el escriba (Esd 7:1), entre los signatarios del pacto sellado (Neh 10:3), y en genealogías tribales de Judá y Simeón.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H8307', 'spa', 'Obstinación, terquedad — firmeza de corazón en sentido negativo, rechazo voluntario a obedecer la palabra de Dios', 'Este sustantivo, que siempre aparece en estado constructo con ''corazón'' (lev/libbam), describe una disposición fija e inflexible: la terquedad u obstinación que rechaza toda corrección. Es el diagnóstico emblemático de Jeremías sobre la condición espiritual de Israel, apareciendo siete veces solo en su profecía (Jer 3:17; 7:24; 9:13; 11:8; 13:10; 16:12; 18:12; 23:17). La palabra proviene de una raíz que significa ''ser firme'', pero su uso es enteramente negativo: un corazón endurecido contra la instrucción divina. Deuteronomio 29:19 advierte contra quien camina en esta obstinación, y el Salmo 81:12 lamenta que Dios entregó a Israel a la dureza de su propio corazón.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H8311', 'spa', 'extender, estirar (miembro anormalmente largo o estirarse uno mismo)', 'Este verbo significa extender o estirar, apareciendo tanto en contextos físicos literales como en un uso metafórico. Levítico 21:18 usa el participio pasivo Qal para un hombre que está ''extendido/deforme''—teniendo un miembro anormalmente largo que lo descalifica del servicio sacerdotal. Levítico 22:23 describe similarmente un animal que está ''extendido/deforme'' en un miembro, haciéndolo inadecuado para sacrificio. Isaías 28:20 cambia a metáfora: la cama es demasiado corta ''para extenderse''—no hay espacio para comodidad o descanso (ilustrando la inadecuación de falsos refugios). La raíz se relaciona con palabras árabes para entrar en un camino o enderezar.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H8313', 'spa', 'Quemar, prender fuego; consumir con fuego, ya sea activamente, en voz pasiva o como estado resultante de haber sido quemado.', 'El verbo שָׂרַף es el término hebreo primario para la acción de quemar, y aparece de manera abrumadora con la expresión בָּאֵשׁ (''con fuego''). Recorre todo el sistema de voces: la quema activa de ídolos, cadáveres y restos sacrificiales (Éx 32:20; Lv 4:12), el ''ser quemado'' pasivo como castigo o purificación (Gn 38:24; Lv 7:17) y el estado resultante ''quemado'' que describe ciudades arruinadas y muros calcinados (1 S 30:3; Neh 4:2). Los contextos rituales predominan: aproximadamente la mitad de las apariciones involucran procedimientos levíticos para eliminar restos sacrificiales fuera del campamento.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H8314a', 'spa', 'serpiente ardiente; serpiente venenosa cuya mordedura abrasa, o serpiente mítica alada/dragón', 'Derivado de la raíz que significa «arder», este sustantivo describe serpientes cuyo veneno produce una sensación abrasadora. En los relatos del desierto, Dios envía «serpientes ardientes» cuyas mordeduras letales castigan la queja de Israel (Nm 21:6), y Moisés recibe la orden de fabricar una réplica de bronce (Nm 21:8). Deuteronomio 8:15 rememora la «serpiente ardiente» del desierto. Los oráculos de Isaías presentan una criatura más mítica: una «serpiente ardiente voladora» (Is 14:29; 30:6), fusionando imaginería natural y sobrenatural. El adjetivo español «ardiente» conserva el vínculo etimológico con el fuego.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H8316', 'spa', 'Quema, conflagración; quemadura o cicatriz en la piel. El sustantivo femenino שְׂרֵפָה (sherefah) designa el acto o resultado de quemar. En la mayoría', 'Quema, conflagración; quemadura o cicatriz en la piel. El sustantivo femenino שְׂרֵפָה (sherefah) designa el acto o resultado de quemar. En la mayoría de sus trece apariciones se refiere a fuego destructivo o quema ritual: la cocción de ladrillos en Babel (Gn 11:3), la quema de la vaca roja (Nm 19:6), los ritos funerarios de quema de especias para los reyes de Judá (2 Cr 16:14; 21:19) y la devastadora conflagración de la tierra o el templo (Is 64:10; Jer 51:25). Un sentido distinto pero relacionado aparece en las regulaciones levíticas sobre enfermedades de la piel, donde designa la marca o cicatriz dejada por una quemadura en la carne, no el evento del fuego en sí.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H8317', 'spa', 'Pulular, bullir; criaturas que se multiplican abundantemente, o (como participio) criatura que pulula o se arrastra. Evoca la vitalidad rebosante de l', 'Pulular, bullir; criaturas que se multiplican abundantemente, o (como participio) criatura que pulula o se arrastra. Evoca la vitalidad rebosante de la creación: aguas que bullen de peces, la tierra que se llena de criaturas, pueblos que se multiplican sin medida. En Génesis 1:20-21 Dios ordena a las aguas ''pulular con enjambres de seres vivientes'', y el verbo reaparece cada vez que la Escritura quiere transmitir una reproducción explosiva y prolífica (Gn 8:17; 9:7; Éx 1:7, sobre Israel en Egipto). La forma participial (ha-shorets) se convierte en un clasificador de animales pequeños que se mueven en enjambres: los ''seres que se arrastran'' de Levítico 11:29-46 cuyo contacto vuelve a uno inmundo.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H8318', 'spa', 'Criaturas que pululan — término colectivo para animales pequeños que bullen en el agua o se arrastran por tierra. El sustantivo שֶׁרֶץ (sherets) es un', 'Criaturas que pululan — término colectivo para animales pequeños que bullen en el agua o se arrastran por tierra. El sustantivo שֶׁרֶץ (sherets) es un término colectivo para criaturas pequeñas que pululan, bullen o se arrastran, abarcando animales acuáticos, reptiles y roedores terrestres e insectos voladores. Aparece en la creación misma (Gn 1:20), en el relato del diluvio (Gn 7:21) y extensamente en las leyes de pureza de Levítico 11, donde ayuda a definir la frontera entre lo limpio y lo inmundo. La amplitud semántica del término es notable: cubre desde criaturas acuáticas que nadan en cardúmenes hasta lagartijas, ratones e insectos de cuatro patas.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H8319', 'spa', 'Silbar, chiflar — sonido sibilante agudo que expresa escarnio sobre ruinas o convoca agentes desde lejos', 'El verbo שָׁרַק describe un sonido agudo y penetrante — un silbido o chiflido — empleado en dos sentidos distintos. Con mayor frecuencia expresa burla ante lugares devastados: los transeúntes ''silban'' ante las ruinas de Jerusalén (1 R 9:8; Jer 19:8; 49:17; 50:13), ante la caída de Tiro (Ez 27:36) y ante la desolación de Israel (Lm 2:15-16). Este silbido mezcla desprecio con estupor. En un segundo uso, Dios ''silba'' para convocar naciones lejanas: ''Silbará por ellos desde los confines de la tierra'' (Is 5:26; 7:18). Zacarías 10:8 reformula la imagen positivamente: Dios silba para reunir a sus redimidos.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H8322', 'spa', 'Silbido, escarnio — silbido burlón dirigido a un lugar arruinado, expresando mofa y horror', 'Shereqah designa el acto de silbar con desprecio, un gesto de escarnio dirigido a un lugar reducido a ruinas por el juicio divino. Aparece exclusivamente en oráculos proféticos de juicio y siempre junto a shammah («desolación»), formando un par fijo que intensifica la imagen de devastación total. Jeremías emplea este binomio repetidamente para describir el destino de Judá y las naciones (Jer 19:8; 25:9, 18; 29:18; 51:37), mientras que Miqueas 6:16 lo aplica al legado de Samaria. Las traducciones al español con «silbido» y «burla» capturan tanto el sonido como la mofa inherente al término.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H8323', 'spa', 'Gobernar, actuar como príncipe; denominativo de שַׂר, ejercer autoridad, regir o enseñorearse sobre otros', 'Verbo denominativo construido sobre שַׂר (''príncipe, gobernante''), que expresa la actividad de gobierno y autoridad principesca. El Hitpael en Números 16:13 lleva un tono peyorativo: la facción de Coré acusa a Moisés de ''enseñorearse'' sobre ellos, de hacerse el príncipe. En cambio, Isaías 32:1 y Proverbios 8:16 usan el Qal para describir un gobierno justo y legítimo. El campo semántico se extiende así desde la autoridad apropiada hasta el abuso de poder. Ester 1:22 amplía el concepto a la jefatura doméstica.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H8324', 'spa', 'acechador hostil, enemigo; quien vigila con intención maliciosa', 'Este sustantivo, que aparece exclusivamente en los Salmos con sufijo de primera persona («mis acechadores/enemigos»), designa adversarios que observan y acechan con propósito maligno. A diferencia del más frecuente אוֹיֵב (enemigo), este término conlleva el matiz de vigilancia y hostilidad al acecho: enemigos que esperan la oportunidad de atacar. El contexto sálmico sitúa sistemáticamente a estos acechadores en oposición al justo sufriente. El salmista ruega dirección por causa de «mis enemigos» (Sal 5:8; 27:11), suplica vindicación contra ellos (Sal 54:5; 59:10) y lamenta su persecución implacable (Sal 56:2).');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H8327', 'spa', 'Echar raíces, arraigarse firmemente; también desarraigar, arrancar de raíz, o ser desarraigado', 'Verbo denominativo construido sobre el sustantivo «raíz» (shoresh), que abarca ambos extremos de la metáfora botánica. En sus formas Hiphil y Poal describe a Israel o a los impíos echando raíces profundas en la tierra (Is 27:6; Jer 12:2), mientras que el Piel expresa el desarraigo violento: Dios arrancando a alguien de la tierra de los vivientes (Sal 52:5). El Pual pasivo en Job 31:8 («sean desarraigados») completa el cuadro: lo que Dios planta, Dios también puede arrancar. Las traducciones españolas «arraigado» y «desarraigará» reflejan con precisión esta polaridad semántica.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H8328', 'spa', 'Raíz — la parte subterránea de una planta; figuradamente, linaje ancestral, origen o causa más profunda de algo', 'Raíz — la parte subterránea de una planta; figuradamente, linaje ancestral, origen o causa más profunda de algo');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H8330', 'spa', 'raíces (arameo, de árboles)', 'Este sustantivo arameo masculino plural con sufijo significa ''raíces'', específicamente raíces de un árbol, apareciendo únicamente en el relato de Daniel sobre el sueño de Nabucodonosor y su cumplimiento. Daniel 4:12 describe el gran árbol del sueño con ''sus raíces'' aún en la tierra después de ser cortado. La orden de dejar el tocón con ''raíces'' en la tierra (4:20, 23) simboliza que el reino de Nabucodonosor será restaurado después de su período de locura: el sistema de raíces permanece viable para rebrotar. La imagen se basa en conocimiento agrícola: un árbol cortado con raíces intactas puede volver a brotar, representando esperanza de restauración después del juicio.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H8333', 'spa', 'Cadena, cadenilla trenzada — trabajo metálico eslabonado para ornamentación sacerdotal y decoración arquitectónica', 'Sharshrah designa cadenas de trabajo metálico trenzado o entrelazado, que aparecen en dos contextos distintos pero relacionados: las vestiduras sagradas y la arquitectura del Templo. En Éxodo 28:14, 22 y 39:15, cadenas de oro de labor trenzada sujetan el pectoral del juicio a las hombreras del efod, un detalle de orfebrería sacerdotal descrito con minuciosa precisión. En 1 Reyes 7:17 y 2 Crónicas 3:5, 15-16, cadenas similares adornan las columnas y el interior del Templo de Salomón. El cognado acadio sharshurratu («cadena, grillete») confirma la profunda antigüedad semítica de este término.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H8334', 'spa', 'Ministrar o servir en una función honorable; como sustantivo, ministro, asistente o servidor de alto rango. A diferencia del más general עָבַד (''traba', 'Ministrar o servir en una función honorable; como sustantivo, ministro, asistente o servidor de alto rango. A diferencia del más general עָבַד (''trabajar, servir como esclavo''), שָׁרַת denota un servicio ministerial digno: el que presta un asistente personal de confianza o un sacerdote en el santuario. José ''ministró'' a Potifar en una posición de confianza (Gn 39:4), Josué fue el ministro personal de Moisés (Éx 24:13), y los levitas ''ministran'' delante del Señor en el tabernáculo (Nm 3:6). La forma Piel intensifica el sentido de servicio dedicado y continuo. Las traducciones distinguen consistentemente este servicio del trabajo servil: español ''ministrar'' frente a ''servir'', alemán ''dienen'' en su sentido elevado.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H8336a', 'spa', 'mármol (piedra blanca para pilares y pavimento)', 'Este sustantivo denota mármol, la piedra blanca o coloreada usada en arquitectura real y construcción de lujo. Ester 1:6 describe el patio del palacio persa con pilares de mármol sosteniendo los toldos. El mismo versículo menciona mármol dos veces más al describir el elaborado pavimento de mosaico (junto con otras piedras preciosas). Cantar de los Cantares 5:15 lo usa metafóricamente: las piernas del amado son ''pilares de mármol asentados sobre bases de oro'', imagen de fuerza y belleza. Los contextos asocian uniformemente el mármol con esplendor real y construcción costosa, apropiado para la estética imperial persa y la imagen idealizada de la poesía amorosa.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H8336b', 'spa', 'Lino fino, biso — lino blanco egipcio de alta calidad usado para vestiduras sacerdotales y mobiliario del tabernáculo', 'Lino fino, biso — lino blanco egipcio de alta calidad usado para vestiduras sacerdotales y mobiliario del tabernáculo');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H8337', 'spa', 'Seis: el número cardinal, usado de forma independiente y como base en compuestos como dieciséis y seiscientos.', 'שֵׁשׁ (masculino) y שִׁשָּׁה (femenino) designan el número cardinal seis y aparecen en textos legales, narrativos y rituales. Los seis días de labor antes del descanso sabático (Éx 20:9) constituyen uno de sus usos teológicamente más resonantes, pues establecen el ritmo de trabajo y adoración en el corazón de la vida israelita. También aparece en medidas (seis codos para la estatura de Goliat, 1 S 17:4), genealogías y numerales compuestos. Su función numérica directa no presenta variación semántica según el contexto.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H8342', 'spa', 'Gozo, alegría, exultación; deleite festivo especialmente ante el favor y la salvación de Dios', 'Gozo, alegría, exultación; deleite festivo especialmente ante el favor y la salvación de Dios');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H8344', 'spa', 'Sesai (nombre personal: hijo de Anac, gigante de Hebrón)', 'Sesai fue uno de tres hijos de Anac, gigantes que vivían en Hebrón cuando Israel entró a Canaán. Su nombre aparece en forma aramea según algunos eruditos. Números 13:22 lista a Sesai entre los descendientes de Anac que los espías vieron en Hebrón, contribuyendo a su informe temeroso. Josué 15:14 registra que Caleb expulsó a Sesai y sus hermanos de Hebrón. Jueces 1:10 repite el relato de Judá derrotando a los tres hermanos anaceos. El nombre marca tanto a un individuo como a un clan de guerreros formidables que controlaron Hebrón hasta la conquista de Israel.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H8345', 'spa', 'Sexto (numeral ordinal que indica posición en una secuencia); también un sexto como medida fraccionaria', 'Sexto (numeral ordinal que indica posición en una secuencia); también un sexto como medida fraccionaria');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H8346', 'spa', 'Sesenta — el número cardinal sesenta, usado en medidas, edades, conteos y períodos de tiempo. El numeral hebreo indeclinable שִׁשִּׁים (sesenta) apare', 'Sesenta — el número cardinal sesenta, usado en medidas, edades, conteos y períodos de tiempo. El numeral hebreo indeclinable שִׁשִּׁים (sesenta) aparece 59 veces en una amplia variedad de contextos: edades antediluvianas (Gn 5:15, 18, 20), medidas arquitectónicas como los sesenta codos de largo del templo de Salomón (1 R 6:2), conteos militares (2 Cr 12:3) y períodos rituales como los sesenta días de purificación tras dar a luz una hija (Lv 12:5). En Cantares 3:7, sesenta valientes custodian la litera de Salomón. El número se combina frecuentemente con otros dígitos para formar edades y medidas compuestas en el Pentateuco y los libros históricos.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H8348', 'spa', 'Sesán; varón de Judá en la genealogía de Jerameel que tuvo hijas pero no hijos', 'Sesán es un nombre propio que pertenece a un descendiente judío de Jerameel en la genealogía del Cronista. Su relato destaca por un arreglo social particular: al no tener hijos varones sino solo hijas, dio a su hija en matrimonio a su siervo egipcio Jarhá (1 Cr 2:34-35), asegurando así la continuidad de su linaje. Las cinco ocurrencias se concentran en 1 Crónicas 2:31-35. La LXX transcribe el nombre de diversas formas como Sosan o Sisan, mientras que las traducciones modernas mantienen transliteraciones consistentes.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H8352', 'spa', 'Set: tercer hijo de Adan y Eva, designado como reemplazo de Abel tras el fratricidio de Cain, ancestro del linaje hasta Noe.', 'Nombre propio del tercer hijo de Adan y Eva, nacido despues de que Cain asesinara a Abel. Eva lo llamo Set, explicando que ''Dios me ha concedido otro descendiente en lugar de Abel'' (Gen 4:25), vinculando el nombre a la raiz שִׁית que significa ''poner, designar.'' A traves de Set se traza la linea genealogica de Adan a Noe registrada en Genesis 5, convirtiendolo en ancestro de toda la humanidad posterior al Diluvio. La Septuaginta traduce el nombre como Σήθ, forma que paso a todas las grandes tradiciones de traduccion. Numeros 24:17 menciona a los ''hijos de Set'' en el oraculo de Balaam, aunque algunos eruditos enmiendan esto como ''hijos de tumulto.''');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H8354', 'spa', 'Beber, consumir líquido; el acto básico de beber agua, vino o cualquier bebida, incluyendo el uso participial para bebedores habituales.', 'שָׁתָה es el verbo hebreo estándar para beber y aparece en prácticamente todo contexto narrativo y legal donde se consumen líquidos. Desde Noé bebiendo vino tras el diluvio (Gn 9:21) hasta Elías bebiendo del arroyo Querit (1 R 17:6), el vocablo posee una satisfactoria concreción física. Se empareja naturalmente con אָכַל (''comer'') en la fórmula ''comieron y bebieron'' que puntúa comidas de pacto, fiestas y actos de hospitalidad a lo largo del Antiguo Testamento. La forma participial puede sustantivarse: ''bebedores de vino'' (Jl 1:5), ''bebedores de sidra'' (Is 24:9), nombrando a la persona por su actividad característica.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H8355', 'spa', 'Beber (arameo); consumir líquido, especialmente vino en un banquete real', 'El verbo arameo para beber, cognado del hebreo שָׁתָה. Sus cinco únicas apariciones se concentran en Daniel 5, durante el fatídico banquete de Belsasar: el rey bebía vino (Dn 5:1), mandó traer los vasos para que bebieran (Dn 5:2-3), y bebieron de los vasos sagrados del templo de Jerusalén (Dn 5:4, 23). Las traducciones al español — ''bebía'', ''bebieron'' — confirman el sentido directo de consumo. Este contexto tan concentrado confiere al verbo un tinte ominoso: banquete sacrílego en la víspera del juicio divino.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H8359', 'spa', 'Urdimbre: los hilos longitudinales fijados en el telar por los que se entreteje la trama transversalmente', 'Término técnico de tejeduría que designa el conjunto de hilos tendidos a lo largo del telar, formando la estructura fija a través de la cual se entrelaza la trama (עֵרֶב). Las nueve apariciones se encuentran en Levítico 13:48-59, dentro de las regulaciones sacerdotales para diagnosticar y tratar la contaminación textil (צָרַעַת). El emparejamiento con עֵרֶב (trama) en cada caso muestra que los sacerdotes israelitas necesitaban un vocabulario textil preciso para examinar las prendas fibra por fibra. El español ''urdimbre'' preserva con exactitud esta antigua distinción técnica del telar.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H8361', 'spa', 'sesenta (arameo); el numeral 60, usado en medidas del templo y datos cronologicos en Esdras y Daniel', 'Este es el numeral arameo para sesenta, presente en Esdras y Daniel. En Esdras 6:3, aparece dos veces en el decreto de Ciro sobre las dimensiones del templo: sesenta codos de alto y sesenta de ancho. Daniel 3:1 describe la estatua de oro de Nabucodonosor como de sesenta codos de altura. Daniel 5:31 indica que Dario el medo tenia unos sesenta y dos anos cuando recibio el reino. El numero aparece en contextos de grandeza imperial, enfatizando la escala monumental de estas estructuras reales y sagradas. Sesenta codos (unos 27 metros) representan una altura imponente.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H8362', 'spa', 'Trasplantar o plantar firmemente; como participio pasivo, ''plantado'' — usado poéticamente de árboles, vides y los justos', 'Este verbo describe el acto deliberado de colocar una planta o árbol en la tierra para que eche raíces profundas. Aparece casi exclusivamente en contextos poéticos y proféticos. La célebre imagen del justo ''plantado junto a corrientes de aguas'' en el Salmo 1:3 y Jeremías 17:8 emplea el participio pasivo de este verbo, al igual que el Salmo 92:13, donde los justos florecen al estar ''plantados en la casa de Jehová''. Ezequiel lo utiliza para el acto soberano de Dios al trasplantar un renuevo de cedro en un monte alto (Ez 17:22-23) y para Judá como vid plantada junto a aguas abundantes (Ez 17:8, 10; 19:10, 13).');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H8366', 'spa', 'Orinar; participio Hifil usado idiomáticamente en ''el que orina contra la pared'' para designar a todo varón', 'Este participio Hifil de שָׁתַן aparece exclusivamente en la expresión fija מַשְׁתִּין בְּקִיר (''el que orina contra la pared''), un modismo hebreo vívido para referirse a ''cualquier varón''. Aparece seis veces, siempre en contextos donde una dinastía o casa enfrenta aniquilación total: no quedará ni un solo varón con vida. El modismo se encuentra en los juicios contra la casa de Nabal (1 Sam 25:22, 34) y contra las casas reales de Jeroboam (1 Re 14:10), Baasa (1 Re 16:11) y Acab (1 Re 21:21; 2 Re 9:8). La fuerza idiomática es lo que importa, más allá de la literalidad de la imagen.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H8367', 'spa', 'calmarse, aquietarse; cesar la agitacion, ya sea del mar, de contiendas o de tumultos', 'Este verbo significa aquietarse, calmarse o cesar, y aparece en el hebreo biblico tardio. En Jonas 1:11-12, se pregunta dos veces que hacer para que el mar se calme durante la tormenta. El Salmo 107:30 celebra como Dios aquieta las olas cuando los marineros claman a el. Proverbios 26:20 observa que sin chismoso, la contienda se apacigua. El verbo describe la transicion de la turbulencia a la tranquilidad, ya sea que se trate de mares embravecidos, conflictos humanos o tumulto general. Es el momento bendito en que el caos cede ante la paz.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H8370', 'spa', 'Setar-Boznai; funcionario persa que, junto con Tatnai, investigó la reconstrucción del templo judío bajo Darío.', 'Nombre propio compuesto de origen persa que designa a un funcionario que servía bajo el gobernador Tatnai en la provincia de Trans-Éufrates durante el reinado de Darío I. Setar-Boznai aparece en Esdras 5-6 como parte de la investigación administrativa sobre si los judíos contaban con autorización real para reconstruir el templo de Jerusalén. Tras confirmar Darío el decreto original de Ciro, Setar-Boznai recibió la orden de apoyar la obra en lugar de obstaculizarla. El nombre posiblemente derive del iranio antiguo, quizá con el significado de ''libertador del imperio'' (Scheftlowitz) o conteniendo el elemento Mithra (Andreas-Marquart). Sus seis apariciones se concentran en Esdras 5:3, 5:6, 6:6 y 6:13.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H8372', 'spa', 'Cámara, cuarto de guardia — habitación lateral que flanquea un complejo de puertas en la arquitectura de templos o palacios. תָּא designa las pequeñas', 'Cámara, cuarto de guardia — habitación lateral que flanquea un complejo de puertas en la arquitectura de templos o palacios. תָּא designa las pequeñas cámaras o alcobas construidas dentro de las estructuras de las puertas del templo visionario de Ezequiel y, en una referencia anterior, el cuarto de guardia del palacio de Salomón (1 R 14:28). De sus 17 ocurrencias, 15 se concentran en Ezequiel 40, donde el profeta mide tres cámaras a cada lado de cada puerta. El BDB señala que la palabra puede ser un arameísmo, cognado con el arameo tawan y el árabe thawa (''habitar''), apuntando a un lugar de alojamiento o recinto cerrado.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H8378', 'spa', 'Deseo, anhelo, apetencia; la cualidad de ser deseable; como verbo Piel, desear activamente algo. Este sustantivo femenino de la raíz אוה (''desear, anh', 'Deseo, anhelo, apetencia; la cualidad de ser deseable; como verbo Piel, desear activamente algo. Este sustantivo femenino de la raíz אוה (''desear, anhelar'') abarca todo el espectro emocional del querer humano. Puede describir el anhelo sano de un corazón justo — ''el deseo de los justos es solamente el bien'' (Prov 11:23) — o la codicia destructiva que llevó a Israel a exigir carne en el desierto, dando a Kibrot-hataava (''sepulcros de la codicia'') su ominoso nombre (Nm 11:34). La única ocurrencia en Génesis 3:6 — donde el árbol prohibido era ''deseable'' para alcanzar sabiduría — revela cómo el deseo puede adherirse a los objetos mismos como cualidad percibida.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H8380', 'spa', 'gemelos, mellizos; dos hijos nacidos juntos del mismo embarazo, ya sean humanos o animales', 'Este sustantivo designa a los gemelos, dos nacidos juntos de un mismo parto. Genesis 25:24 describe el embarazo de Rebeca: habia gemelos en su vientre (Jacob y Esau). Genesis 38:27 presenta de manera similar a los hijos gemelos de Tamar. El Cantar de los Cantares emplea el termino poeticamente al describir a la amada: sus pechos como dos cervatillos, gemelos de gacela (4:5; 7:3), evocando simetria y belleza. En la narrativa biblica, los gemelos suelen senalar un destino singular: la rivalidad entre Jacob y Esau, el dramatico nacimiento de Fares y Zera. En la poesia, la imagen gemelar sugiere emparejamiento perfecto y armonia.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H8382', 'spa', 'Estar emparejado, hermanado; parir gemelos; estar acoplado simétricamente', 'Verbo denominativo de תְּאוֹם (gemelo), que abarca tanto el acoplamiento arquitectónico como el parto de gemelos. En Éxodo, los marcos del tabernáculo deben estar ''hermanados'' en la parte inferior y completos en la superior (Éx 26:24; 36:29) — un término técnico de carpintería para tablas ensambladas a ras. En el Cantar de los Cantares, los dientes de la amada se comparan con ovejas que paren gemelos (Cnt 4:2; 6:6), cada pieza perfectamente emparejada con su par. El español refleja ambos sentidos: ''completos/parejos'' para el uso estructural y ''gemelos'' para la imagen pastoril.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H8384', 'spa', 'Higuera (el árbol cultivado) o higo (su fruto comestible) — símbolo de paz, provisión y juicio profético', 'Higuera (el árbol cultivado) o higo (su fruto comestible) — símbolo de paz, provisión y juicio profético');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H8388a', 'spa', 'Torcer, inclinar, trazar (el curso de un límite territorial); delinear el recorrido de una frontera.', 'Verbo técnico de agrimensura y descripción de límites territoriales, que aparece casi exclusivamente en los relatos de reparto tribal de Josué. Describe cómo una línea fronteriza ''gira'' o ''se inclina'' al trazar su curso de un punto de referencia al siguiente. Cinco de sus seis apariciones se encuentran en Josué 15 y 18, delimitando las fronteras de Judá y Benjamín, mientras que la sexta aparece en Josué 19:13 para Zabulón. La evidencia multilingüe es reveladora: el inglés lo traduce como ''marked'' o ''marked out'', el español usa ''trazó'' y el francés ''marqua'', convergiendo todos en la idea de delinear un trayecto.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H8389', 'spa', 'Forma exterior, figura, apariencia — la silueta visible o porte físico de una persona. El sustantivo תֹּאַר (toar) designa la forma exterior, figura o', 'Forma exterior, figura, apariencia — la silueta visible o porte físico de una persona. El sustantivo תֹּאַר (toar) designa la forma exterior, figura o apariencia física: la silueta visible que una persona presenta a la vista. Casi siempre describe la belleza humana o su ausencia, típicamente emparejado con מַרְאֶה (aspecto/apariencia) en la frase יְפַת/יְפֵה תֹּאַר (''hermosa/hermoso de forma''). Raquel (Gn 29:17), José (Gn 39:6), Abigail (1 Sam 25:3) y Ester (Est 2:7) reciben esta descripción. En marcado contraste, el Siervo Sufriente no tiene ''forma'' que nos atraiga (Is 52:14; 53:2).');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H8392', 'spa', 'Arca o embarcación de salvación; la gran nave de Noé y la cesta de papiro de Moisés, ambas instrumentos del rescate divino', 'Arca o embarcación de salvación; la gran nave de Noé y la cesta de papiro de Moisés, ambas instrumentos del rescate divino');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H8393', 'spa', 'Producto, rendimiento: cosechas de la tierra; ingresos o ganancias del trabajo o el comercio; la cosecha como acontecimiento', 'Producto, rendimiento: cosechas de la tierra; ingresos o ganancias del trabajo o el comercio; la cosecha como acontecimiento');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H8394', 'spa', 'Entendimiento, discernimiento, perspicacia; la facultad de comprensión y la habilidad práctica que de ella se deriva.', 'Entendimiento, discernimiento, perspicacia; la facultad de comprensión y la habilidad práctica que de ella se deriva.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H8396', 'spa', 'Tabor — Monte Tabor en el valle de Jezreel, una ciudad levítica y una encina emblemática cerca de Betel', 'Tabor designa principalmente el prominente monte en forma de cúpula que se eleva en el extremo noreste del valle de Jezreel, en la baja Galilea, visible desde grandes distancias. Aparece de manera memorable en Jueces 4:6-14, donde Débora ordenó a Barac reunir diez mil hombres en el monte Tabor antes de la victoria decisiva sobre los carros de Sísara. Oseas 5:1 lo denuncia como un lazo, posiblemente aludiendo a culto ilícito allí, y Jeremías 46:18 compara a un rey invasor con Tabor entre los montes. El salmista celebra a Tabor junto con Hermón como montes que se gozan en el nombre de Dios (Sal 89:12). El nombre también se aplica a una ciudad levítica y a una encina cerca de Betel en territorio de Benjamín.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H8398', 'spa', 'Mundo, tierra habitada — sinónimo poético del ámbito terrestre como dominio creativo de Dios.', 'Mundo, tierra habitada — sinónimo poético del ámbito terrestre como dominio creativo de Dios.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H8401', 'spa', 'Paja, tamo — tallos de grano trillados usados como forraje para animales, material de construcción o figura de insignificancia. תֶּבֶן se refiere a lo', 'Paja, tamo — tallos de grano trillados usados como forraje para animales, material de construcción o figura de insignificancia. תֶּבֶן se refiere a los tallos secos y cortados que quedan después de trillar el grano: la paja que servía al antiguo Israel como alimento para animales y como aglutinante esencial en la fabricación de ladrillos de barro. Las narrativas del Éxodo (5:7-18) ilustran poderosamente su importancia: la exigencia del faraón de que los israelitas recogieran su propia paja manteniendo su cuota de ladrillos se convierte en emblema de trabajo opresivo. En otros pasajes, la paja alimenta camellos (Gn 24:25), asnos (Jue 19:19) y ganado (Is 11:7). Proféticamente se vuelve metáfora de lo insustancial: Jeremías la contrasta con el grano (23:28) y Job compara al impío con paja arrastrada por el viento (21:18).');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H8402', 'spa', 'Tibni (nombre personal: rival de Omri por el trono de Israel)', 'Tibni hijo de Ginat fue un reclamante rival al trono de Israel después del asesinato del rey Ela, compitiendo contra Omri durante seis años. 1 Reyes 16:21-22 registra que cuando Zimri murió, ''el pueblo de Israel estaba dividido'': la mitad seguía a Tibni y la mitad a Omri. Eventualmente la facción de Omri prevaleció, Tibni murió, y Omri se convirtió en rey único. El nombre puede tener conexiones fenicias (comparar con el rey sidonio Tabnit). Tibni representa la inestabilidad política y división civil que plagó al norte de Israel durante sus transiciones dinásticas.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H8403', 'spa', 'Forma visible, semejanza o imagen; también un patrón constructivo, plano o diseño para edificar estructuras sagradas. תַּבְנִית abarca tanto el aspect', 'Forma visible, semejanza o imagen; también un patrón constructivo, plano o diseño para edificar estructuras sagradas. תַּבְנִית abarca tanto el aspecto de algo como el diseño a partir del cual se construye. En Deuteronomio 4:16-18 advierte contra hacer cualquier ''forma'' o ''semejanza'' como ídolo — la figura visible de una criatura. Pero en Éxodo 25:9, 40 y 1 Crónicas 28:11-19, la misma palabra se convierte en el ''patrón'' o ''plano'' divinamente revelado para el tabernáculo y el templo. La palabra así tiende un puente entre representación e instrucción: un sentido capta la apariencia exterior de algo, el otro su diseño arquitectónico previsto.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H8405', 'spa', 'Tebes (nombre de lugar: ciudad cerca de Siquem, sitio de la muerte de Abimelec)', 'Tebes fue una ciudad fortificada cerca de Siquem, famosa como el lugar donde Abimelec encontró su fin ignominioso. Jueces 9:50 reporta que Abimelec sitió Tebes, pero cuando se acercó a la torre para quemarla, una mujer dejó caer una piedra de molino sobre su cabeza, fracturándole el cráneo. Ordenó a su escudero que lo matara para que no se dijera que una mujer lo mató. 2 Samuel 11:21 se refiere retóricamente a este incidente: ''¿Quién mató a Abimelec? ¿No arrojó una mujer una piedra de molino sobre él desde el muro en Tebes?'' El sitio se identifica con la moderna Tubas, a unas cuatro horas al norte de Siquem.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H8406', 'spa', 'quebradizo, frágil — fragmentado o fácilmente quebrantable, describe parte de la estatua de Nabucodonosor', 'Este participio pasivo arameo aparece en Daniel 2:42, describiendo parte de los pies del cuarto reino como ''frágil'' o ''quebradizo''. Los pies de la estatua eran en parte de hierro y en parte de barro: fuertes y a la vez frágiles, reflejando un reino poderoso pero internamente fracturado. El participio sugiere la cualidad de ser quebrantable o de encontrarse ya en un estado de ruptura. Esto anticipa la piedra que destruirá la estatua entera.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H8407', 'spa', 'Tiglat-pileser III, rey de Asiria (745-727 a.C.), conquistador del norte de Israel y estados vasallos del Levante', 'El nombre תִּגְלַת פִּלְאֶסֶר (Tiglat-pileser) se refiere al emperador neoasirio Tukulti-apil-Esharra III, cuyo nombre significa ''mi confianza está en el hijo de Esharra''. En la Biblia hebrea coexisten dos tradiciones ortográficas: la grafía de Reyes, תִּגְלַת פִּלְאֶסֶר (2 R 15:29; 16:7, 10), y la variante de Crónicas, תִּלְּגַת פִּלְנְאֶסֶר (1 Cr 5:6, 26; 2 Cr 28:20). Deportó a las tribus transjordanas y conquistó Galilea, convirtiendo a Acaz de Judá en su tributario. Su política de deportaciones masivas allanó el camino para la posterior caída de Samaria.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H8408', 'spa', 'beneficios — actos de bondad o favor, particularmente bendiciones divinas que merecen respuesta de gratitud', 'Este sustantivo aparece en el Salmo 116:12 con un sufijo arameo: ''todos sus beneficios para conmigo''. El salmista pregunta retóricamente: ''¿Qué pagaré al Señor por todos sus beneficios?'' La palabra denota actos de bondad o favor, especialmente favores divinos. El plural subraya la multiplicidad de las obras generosas de Dios. La pregunta conduce a la respuesta: una vida de acción de gracias, votos cumplidos y testimonio público.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H8409', 'spa', 'hostilidad, contienda — conflicto u oposición, particularmente la disciplina divina', 'Este sustantivo denota contienda, lucha u hostilidad. El Salmo 39:10 (v. 11 en versiones en español) dice: ''por la hostilidad de tu mano yo me consumo''. La palabra sugiere oposición o conflicto activo. Aquí describe la acción disciplinaria de Dios: su ''mano'' trayendo juicio correctivo. El salmista reconoce que el sufrimiento no proviene de un destino impersonal, sino de la corrección intencional, aunque dolorosa, de Dios. El sustantivo capta la dimensión adversarial de la disciplina divina.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H8414', 'spa', 'Informe, caos, vacío o nada — el vacío sin forma previo a la creación, un desierto desolado, o vanidad moral-teológica.', 'Informe, caos, vacío o nada — el vacío sin forma previo a la creación, un desierto desolado, o vanidad moral-teológica.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H8415', 'spa', 'El abismo, las profundidades — aguas primordiales, profundidades oceánicas, manantiales subterráneos o metáfora de lo insondable.', 'El abismo, las profundidades — aguas primordiales, profundidades oceánicas, manantiales subterráneos o metáfora de lo insondable.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H8416', 'spa', 'Alabanza, canto de alabanza o renombre; celebración verbal y musical del carácter y las obras de Dios, y de la fama que confieren. תְּהִלָּה es la pal', 'Alabanza, canto de alabanza o renombre; celebración verbal y musical del carácter y las obras de Dios, y de la fama que confieren. תְּהִלָּה es la palabra que da nombre a todo el libro de los Salmos en hebreo (Sefer Tehillim). Se mueve fluidamente entre el acto de alabar, el canto que vehicula la alabanza y el renombre que resulta de ella. Cuando Moisés declara que Dios es ''tu alabanza'' (Dt 10:21), quiere decir tanto el objeto de adoración como la fuente de la fama de Israel. Jeremías la usa de otro modo: las naciones se convierten en ''alabanza'' o pierden su alabanza según Dios las exalta o las juzga.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H8417', 'spa', 'error, insensatez — equivocación o falta moral, posiblemente en Job 4:18 (aunque el texto es incierto)', 'Este sustantivo aparece en Job 4:18, aunque el texto es objeto de debate. Elifaz afirma que Dios «halla error en sus ángeles» o insensatez. Si la lectura es correcta, el sustantivo denota una equivocación o falta moral: ni siquiera los seres celestiales están exentos de reproche ante Dios. Sin embargo, muchos eruditos prefieren la lectura «falta de confianza» (tiflá), y las variantes textuales sugieren confusión temprana entre ambos términos. En cualquier caso, el versículo afirma la santidad trascendente de Dios.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H8418', 'spa', 'procesiones — marchas ceremoniales formales, especialmente para culto y dedicación', 'Este sustantivo plural designa procesiones o marchas formales. En Nehemías 12:31 se describen dos «procesiones de acción de gracias» durante la dedicación de la muralla reconstruida de Jerusalén. Estas procesiones avanzaban en direcciones opuestas sobre la muralla, con coros, músicos y líderes celebrando públicamente la protección de Dios. La palabra enfatiza un movimiento organizado y ceremonial con propósito religioso: la adoración hecha visible y comunitaria. Tales procesiones encarnaban la identidad de Israel como pueblo reunido en torno a Yahvé.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H8419', 'spa', 'Perversidad, tortuosidad — habla, conducta o carácter moralmente torcido, usado casi exclusivamente en Proverbios', 'Este sustantivo, siempre en forma plural, describe lo que es moralmente torcido, distorsionado o invertido, lo opuesto a la integridad recta. Proverbios lo despliega como vocabulario concentrado de corrupción moral: habla perversa (Pr 2:12; 10:31-32; 23:33), un ''hombre de perversidades'' que siembra discordia (Pr 16:28), y la maquinación de planes torcidos (Pr 6:14; 16:30). Su única aparición fuera de Proverbios se halla en el Cántico de Moisés (Dt 32:20), donde Israel es llamado ''generación de perversidades'', hijos infieles en quienes no hay firmeza. La raíz sugiere una inversión fundamental de lo que es recto.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H8420', 'spa', 'marca, señal (símbolo visible para identificación o protección)', 'Este sustantivo denota una marca o señal, ya sea escrita/inscrita o hecha en el cuerpo. Job 31:35 lo usa para la ''marca'' o firma de Job—su atestación escrita o documento sellado que prueba su integridad. Ezequiel 9:4 y 9:6 lo usan para la marca colocada en las frentes de los justos en Jerusalén, eximiéndolos del juicio venidero: ''pon una marca en las frentes de los hombres que suspiran y gimen por todas las abominaciones.'' La marca protectora distingue a los fieles de los idólatras, asegurando que los ángeles destructores los perdonen. Esta imagen influyó en el simbolismo apocalíptico posterior del sellamiento de los siervos de Dios.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H8421', 'spa', 'Volver, regresar (arameo); en Haf''el, restaurar, devolver o responder.', 'Verbo arameo equivalente al hebreo שׁוּב, que aparece exclusivamente en Daniel y Esdras. En la conjugacion Pe''al (Qal) describe el conmovedor retorno de la razon y el esplendor real de Nabucodonosor tras su periodo de locura (Dan 4:34, 36). La conjugacion Haf''el (causativa) se extiende a dos funciones: restaurar objetos fisicos, como cuando Ciro decreta que los utensilios del templo sean devueltos a Jerusalen (Esd 6:5), y devolver una respuesta verbal o replica (Esd 5:5, 11; Dan 2:14; 3:16).');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H8422', 'spa', 'Tubal: hijo de Jafet y el pueblo o region descendiente de el, ubicado en el este de Asia Menor, frecuentemente emparejado con Mesec.', 'Nombre propio que identifica tanto a un hijo de Jafet en la Tabla de las Naciones como al pueblo o territorio asociado con el, generalmente ubicado en la Anatolia oriental, cerca de la antigua Capadocia. Tubal aparece en las genealogias de Genesis 10:2 y 1 Cronicas 1:5 junto a sus hermanos Magog, Madai, Javan y Mesec. En Ezequiel, Tubal y Mesec se emparejan sistematicamente como pueblos comerciantes que exportaban esclavos y utensilios de bronce (Ez 27:13), como guerreros caidos en el Seol (Ez 32:26) y como aliados de Gog en el gran conflicto escatologico (Ez 38:2-3; 39:1). Isaias 66:19 enumera a Tubal entre las naciones lejanas a quienes se proclamara la gloria de Dios.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H8424', 'spa', 'tristeza, pesar; dolor emocional o pesadumbre del corazon, frecuentemente contrastado con el gozo en la literatura sapiencial', 'Este sustantivo designa la tristeza o el pesar, un dolor emocional y pesadumbre interior. El Salmo 119:28 exclama: «Mi alma se deshace de tristeza». Proverbios lo emplea en contrastes sapienciales: el hijo sabio alegra al padre, pero el necio es tristeza para su madre (10:1). Proverbios 14:13 observa que aun en la risa puede doler el corazon, y el final del gozo puede ser tristeza. Proverbios 17:21 senala que el padre del necio no tiene alegria. La literatura sapiencial reconoce la tristeza como sombra inseparable del gozo: el peso de la necedad, la perdida y las decepciones de la vida. Ni la risa logra desterrarla por completo.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H8425', 'spa', 'Togarmá; nombre de un territorio o pueblo del norte, en Armenia o Asia Menor, descendiente de Jafet', 'Este nombre geografico y etnico designa un territorio septentrional, probablemente en Armenia o el noroeste de Asia Menor. Genesis 10:3 enumera a Togarmá como descendiente de Gomer (linaje de Jafet) en la Tabla de las Naciones, y 1 Cronicas 1:6 repite la genealogia. Ezequiel 27:14 menciona a Bet-togarmá (casa de Togarmá) como comerciante de caballos, corceles de guerra y mulos con Tiro. Ezequiel 38:6 incluye a Togarmá del extremo norte entre los aliados de Gog. Las fuentes antiguas asocian este nombre con el territorio armenio. En la cosmografia de Ezequiel, Togarmá representa el norte lejano, confin del mundo conocido, fuente de caballos preciados y aliado de enemigos escatologicos.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H8426', 'spa', 'Acción de gracias, alabanza o confesión ofrecida a Dios; también ofrenda de gratitud o coro procesional de acción de gracias.', 'Acción de gracias, alabanza o confesión ofrecida a Dios; también ofrenda de gratitud o coro procesional de acción de gracias.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H8427', 'spa', 'marcar, garabatear (hacer marcas en una superficie)', 'Este verbo denominativo significa hacer marcas o poner una señal, derivado del sustantivo ''tav'' (marca). 1 Samuel 21:14 describe a David fingiendo locura ante Aquis: ''garabateó en las puertas de la puerta'' y dejó que la saliva corriera por su barba (aunque existen variantes textuales y lecturas alternativas—algunos sugieren ''tamborileó''). Ezequiel 9:4 usa el Hiphil con acusativo cognado: ''pon una marca sobre'' las frentes de los fieles—inscribe activamente la señal protectora. Los contextos involucran marcado errático (la falsa locura de David) o señalamiento intencional (protección divina). La raíz se conecta con la letra tav y el concepto de hacer señales visibles.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H8428', 'spa', 'afligir, provocar — causar dolor o irritación, usado de Israel poniendo a prueba a Dios', 'Este verbo en Hifil significa causar dolor, herir o provocar. En el Salmo 78:41 se dice que Israel «afligió al Santo de Israel» mediante pruebas repetidas e incredulidad. La raíz se relaciona con términos arameos para arrepentimiento o aflicción, sugiriendo que causaron pesar o irritación a Dios. El verbo paralelo es «tentaron», enfatizando la exploración rebelde de la paciencia divina. El lenguaje antropopático —Dios siendo afligido— subraya la dimensión relacional de la infidelidad al pacto.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H8429', 'spa', 'asombrado, alarmado — estar sobrecogido o lleno de estupor, particularmente ante un evento milagroso', 'Este verbo arameo significa estar sobrecogido o asombrado. En Daniel 3:24, Nabucodonosor «se asombró» al ver cuatro hombres caminando en el horno de fuego en lugar de los tres que había arrojado. El verbo capta su estupefacción ante la preservación milagrosa y la misteriosa cuarta figura. El asombro del rey se convierte en el eje narrativo que lo lleva a reconocer al Dios de Sadrac, Mesac y Abednego.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H8430', 'spa', 'Tóaj/Tohú — nombre propio de un antepasado de Samuel, variante ortográfica de Tohú en 1 Samuel 1:1', 'Tóaj aparece en 1 Crónicas 6:34 como antepasado del profeta Samuel, correspondiendo a Tohú en 1 Samuel 1:1. La variación refleja distintas tradiciones textuales o diferencias de pronunciación dialectal. Las genealogías servían para establecer legitimidad: la ascendencia levítica de Samuel validaba sus funciones sacerdotales a pesar de no descender de Aarón. La Septuaginta muestra variaciones adicionales, algo común en nombres propios entre manuscritos.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H8431', 'spa', 'Esperanza, expectativa; sustantivo abstracto que denota un resultado anticipado, ya sea cumplido, diferido o perdido.', 'Derivado de la raíz yahal (''esperar, confiar''), este sustantivo capta la cualidad de la espera expectante y su resultado anticipado. Proverbios 13:12 ofrece su uso más memorable: ''La esperanza que se demora es tormento del corazón'', una frase que resuena a través de las culturas. El vocablo abarca desde la expectativa confiada (Sal 39:7, ''mi esperanza está en ti'') hasta las expectativas frustradas de los impíos (Prov 10:28; 11:7). En Lamentaciones 3:18, el poeta clama que su fortaleza y esperanza han perecido, alcanzando el punto más profundo de la desesperación. El español ''esperanza'' refleja fielmente la cualidad cálida y prospectiva de este término.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H8432', 'spa', 'Medio, centro, interior; espacialmente la zona central; relacionalmente ''entre'' personas o pueblos; el punto medio o interior.', 'תָּוֶךְ es una de esas palabras silenciosas y estructurales que aparecen por doquier pero configuran el sentido de manera profunda. Sitúa las cosas en el centro de espacios, pueblos y acontecimientos: desde el árbol ''en medio del jardín'' (Gn 2:9) hasta Dios morando ''entre'' su pueblo (Éx 25:8). Casi siempre regida por una preposición (בְּתוֹךְ ''en medio de,'' מִתּוֹךְ ''de en medio de,'' אֶל־תּוֹךְ ''hacia el medio de''), funciona menos como sustantivo independiente y más como ancla relacional. La evidencia multilingüe revela una escisión reveladora: cuando el referente es espacial, el árabe usa وَسَط, pero cuando se trata de una comunidad de personas, cambia a بَيْن (''entre''), mostrando que los sentidos espacial y social son genuinamente distintos.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H8433a', 'spa', 'reprensión, corrección; palabras severas de corrección o castigo, ya sea de origen divino o humano', 'Este sustantivo designa la reprensión o corrección severa: palabras cortantes que acompañan el juicio. En 2 Reyes 19:3 e Isaías 37:3 describe la crisis de Jerusalén como un día de angustia, de reprensión y de vergüenza. Oseas 5:9 advierte que Efraín quedará en desolación en el día de la reprensión. El Salmo 149:7 convoca a ejecutar castigos sobre las naciones. No se trata de una amonestación suave, sino de una corrección que hiere y purifica, donde la reprensión verbal se funde con el castigo ejecutado.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H8433b', 'spa', 'Reprensión, corrección o argumento razonado; reproche verbal dirigido a la reforma moral o queja formal presentada ante Dios', 'Reprensión, corrección o argumento razonado; reproche verbal dirigido a la reforma moral o queja formal presentada ante Dios');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H8434', 'spa', 'Tolad — nombre de lugar en el territorio de Simeón, posiblemente idéntico a Eltolad', 'Tolad aparece en 1 Crónicas 4:29 como una ciudad dentro de la herencia de Simeón. Probablemente es la misma localidad que Eltolad, mencionada en Josué 15:30 y 19:4, con una forma abreviada del nombre. La Septuaginta presenta variantes textuales. Las ciudades simeonitas estaban en realidad dentro del territorio más amplio de Judá, lo cual refleja la absorción gradual de Simeón en Judá. Estas listas de ciudades preservan la memoria territorial antigua incluso después de que las realidades políticas cambiaran.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H8435', 'spa', 'Generaciones, registro genealógico — crónicas de descendencia familiar; fórmula estructural de Génesis (''estas son las toledot de...'').', 'Generaciones, registro genealógico — crónicas de descendencia familiar; fórmula estructural de Génesis (''estas son las toledot de...'').');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H8437', 'spa', 'atormentadores, burladores — los que afligen o se mofan; usado para los captores babilónicos que exigían cantos', 'Este sustantivo plural disputado en el Salmo 137:3 se refiere a quienes atormentaban a Israel en el exilio. Los babilonios que los habían devastado les exigían «cantos de Sion», una burla cruel. La palabra podría derivar de una raíz que significa ''lamentarse'' (haciendo de los atormentadores ''los que nos hicieron llorar'') o ''despojar''. Las variantes textuales sugieren incertidumbre temprana. En cualquier caso, el término captura la crueldad psicológica del exilio: ser forzados a interpretar cantos sagrados como entretenimiento para los captores.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H8438a', 'spa', 'gusano; larvas o gusanos, o tinte escarlata producido por el insecto coccus ilicis, según el contexto', 'Este sustantivo abarca dos sentidos emparentados: gusanos literales (larvas) y el tinte escarlata obtenido de un insecto. Éxodo 16:20 describe el maná criando gusanos al conservarse de un día para otro. Isaías 1:18 lo emplea en la célebre promesa: aunque vuestros pecados sean como la grana, como la nieve serán emblanquecidos. Lamentaciones 4:5 evoca a los criados entre escarlata que ahora yacen sobre cenizas. El tinte procedía de los cuerpos triturados del coccus ilicis, creando el vínculo lingüístico entre gusano y carmesí: una misma criatura que representa tanto la descomposición como la belleza costosa.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H8438b', 'spa', 'Gusano o larva (literal/figurado); material tintóreo escarlata del insecto coccus ilicis usado en los tejidos del tabernáculo.', 'Gusano o larva (literal/figurado); material tintóreo escarlata del insecto coccus ilicis usado en los tejidos del tabernáculo.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H8439', 'spa', 'Tolá; nombre propio de un hijo de Isacar y de un juez de Israel de la misma línea tribal.', 'Tolá es un nombre personal que aparece en dos figuras distintas pero genealógicamente conectadas. El primero es un hijo de Isacar incluido entre quienes descendieron a Egipto con Jacob (Gn 46:13), que se convierte en ancestro del clan tolaíta (Nm 26:23). El segundo es un juez de Israel de la tribu de Isacar que juzgó a Israel durante veintitrés años tras la muerte de Abimelec (Jue 10:1). La genealogía de Crónicas (1 Cr 7:1-2) vincula ambas figuras dentro de la línea isacarita. El nombre podría derivar de la palabra para ''gusano'' o ''escarlata'', conectándose con la industria del tinte tolaat, aunque en contexto funciona puramente como nombre propio.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H8440', 'spa', 'tolaíta — adjetivo gentilicio para los descendientes de Tola, usado colectivamente para el clan', 'Esta forma gentilicia aparece en Números 26:23 en el censo de los clanes de Isacar. ''El tolaíta'', con artículo definido, se refiere colectivamente a todos los descendientes de Tola. Estas designaciones clínicas organizaban las unidades militares, determinaban las posiciones de campamento y eventualmente guiaban la distribución de tierras. El censo demostraba que, a pesar de las dificultades del desierto, las tribus de Israel permanecían intactas e identificables: Dios había preservado la estructura del pueblo al que prometió llevar a Canaán.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H8441', 'spa', 'Abominación, cosa o práctica detestable; algo moral o ritualmente aborrecible ante Dios o culturalmente repugnante.', 'תּוֹעֵבָה es una de las palabras de repulsión moral más enérgicas de la Biblia hebrea. Marca acciones, objetos o prácticas como profundamente ofensivos a la santidad de Dios. Cubre tanto la impureza ritual --como consumir alimento inmundo (Dt 14:3) o el asco de Egipto ante las costumbres sacrificiales hebreas (Éx 8:26)-- como graves transgresiones morales como la idolatría, el sacrificio de niños y el pecado sexual (Lv 18:22, 26-30). La forma plural domina en los catálogos proféticos de Ezequiel sobre las transgresiones acumuladas de Israel, mientras que el singular apunta a actos ofensivos específicos.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H8443', 'spa', 'eminencia, alturas; cimas elevadas o cuernos imponentes, que representan elevación, fuerza o acumulación preciosa', 'Este sustantivo designa la eminencia, las alturas o los rasgos imponentes. En los oráculos de Balaam (Nm 23:22; 24:8) describe la fuerza de Israel como ''los cuernos elevados del búfalo'', un poder que se alza de forma impresionante. El Salmo 95:4 celebra la soberanía divina: las cumbres de los montes son suyas. Job 22:25 es más difícil, quizá aludiendo a plata en abundancia o al Todopoderoso como fortaleza elevada. El término enfatiza la dimensión vertical: ya sean cimas geológicas, cuernos de toro o barras de plata, evoca altura y poderío imponentes.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H8444', 'spa', 'Salida o extremo de un límite territorial; escape o liberación de la muerte; fuente o manantial de vida', 'Salida o extremo de un límite territorial; escape o liberación de la muerte; fuente o manantial de vida');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H8446', 'spa', 'Espiar, explorar o investigar; también como participio: comerciante, mercader; en Hifil: aventajar o sobresalir', 'Espiar, explorar o investigar; también como participio: comerciante, mercader; en Hifil: aventajar o sobresalir');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H8447', 'spa', 'turno, trenza; ocasión u oportunidad (de personas); adornos trenzados o engarzados (de cabello u oro)', 'Este término poco frecuente aparece en contextos de belleza y de oportunidad. En el Cantar de los Cantares describe adornos trenzados o engarzados, quizá cabello adornado con hilos de oro (1:10-11). En Ester designa el turno de cada joven para su noche con el rey (2:12, 15). Las traducciones oscilan entre ''pendientes'' u ''ornamentos'' y ''turno'', reflejando el doble alcance semántico: arreglos decorativos y ocasiones sucesivas. La idea raíz parece ser ''disposición en secuencia'', ya sea de hebras trenzadas o de turnos ordenados.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H8448', 'spa', 'manera, costumbre — un modo de hacer las cosas o patrón establecido; texto posiblemente corrupto en 1 Crónicas 17:17', 'Este sustantivo normalmente significa ''turno'' o ''manera'', pero en 1 Crónicas 17:17 la frase es notoriamente difícil. El texto dice algo como ''manera del hombre'' o ''costumbre de la humanidad'', pero el significado sigue siendo oscuro. El paralelo en 2 Samuel 7:19 tiene ''torá del hombre'', igualmente enigmático. Algunos proponen enmendar el texto a ''forma'' o ''rango''. El contexto es David maravillándose de que Dios se preocupara por su casa, pero la expresión exacta de ese asombro es textualmente incierta.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H8449', 'spa', 'tórtola — ave migratoria ofrecida como sacrificio en la ley levítica y empleada como figura de vulnerabilidad. El sustantivo tor es un nombre onomatop', 'tórtola — ave migratoria ofrecida como sacrificio en la ley levítica y empleada como figura de vulnerabilidad. El sustantivo tor es un nombre onomatopéyico que imita el suave arrullo de la tórtola (Streptopelia turtur), ave migratoria cuya llegada anunciaba la primavera en la Palestina antigua. De sus 14 apariciones, la mayoría se encuentra en las regulaciones sacrificiales levíticas, donde un par de tórtolas servía como ofrenda del pobre, el mismo sacrificio que María y José llevaron en la presentación de Jesús (cf. Lv 12:8; Lc 2:24). Jeremías señala su fidelidad migratoria (Jer 8:7), el Cantar de los Cantares celebra el sonido de su voz como señal de primavera (Cnt 2:12), y el Salmo 74:19 representa conmovedoramente al pueblo de Dios como una tórtola vulnerable.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H8450', 'spa', 'Toros, bueyes — termino arameo para ganado bovino, usado para animales sacrificiales y bestias del campo.', 'Torin es el plural arameo de tor (''toro, buey''), cognado del hebreo שׁוֹר. Aparece siete veces en las secciones arameas de Esdras y Daniel, cumpliendo dos funciones vividas. En Esdras designa los toros sacrificiales requeridos para el Templo reconstruido: ''todo lo que sea necesario, toros, carneros y corderos'' (Esd 6:9, 17; 7:17). En Daniel describe las bestias del campo cuya hierba comio Nabucodonosor durante su periodo de locura (Dan 4:25, 32, 33; 5:21). El termino captura consistentemente el sentido de ganado bovino en contextos tanto cultuales como narrativos.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H8451', 'spa', 'Torá, ley, instrucción; la Ley mosaica como legislación divina del pacto, estatutos y regulaciones específicos, o enseñanza humana/profética.', 'תּוֹרָה es mucho más rica de lo que sugiere la palabra ''ley.'' Derivada del verbo יָרָה (''lanzar, dirigir, instruir''), significa fundamentalmente ''dirección'' o ''guía,'' y esa raíz pedagógica nunca desaparece del todo, ni siquiera cuando el vocablo designa el cuerpo legislativo más autoritativo de la vida de Israel. En su uso mayoritario abrumador (203 de 222 apariciones), תּוֹרָה se refiere a la instrucción mosaica del pacto: ''la Torá del SEÑOR,'' ''la Torá de Moisés'' o simplemente ''la Torá'' con artículo. Pero Proverbios conserva el sentido más antiguo y amplio, donde la תּוֹרָה de una madre es su enseñanza (Pr 1:8; 6:20) y la de un padre sabio, su instrucción (Pr 4:2). El plural תּוֹרֹת nombra conjuntos específicos de regulaciones, especialmente en la legislación ritual de Levítico.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H8452', 'spa', 'instrucción, ley, Torá — enseñanza y dirección divina, especialmente la ley mosaica y sus principios', 'Torá es uno de los términos teológicos más importantes del Antiguo Testamento. Aunque frecuentemente se traduce como ''ley'', su significado fundamental es ''instrucción'' o ''enseñanza''. Abarca la voluntad revelada de Dios: mandamientos específicos, narrativa, sabiduría y relación de pacto. Torá puede referirse a la instrucción paterna, la enseñanza profética o, de manera central, al pacto mosaico. La palabra enfatiza la guía para la vida: no reglas arbitrarias sino el camino de sabiduría y bendición. El judaísmo posexílico intensificó el estudio y la observancia de la Torá como identidad del pacto.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H8453a', 'spa', 'Extranjero residente, forastero — persona no nativa que habita en una comunidad con diversos grados de permanencia. El sustantivo toshav designa a alg', 'Extranjero residente, forastero — persona no nativa que habita en una comunidad con diversos grados de permanencia. El sustantivo toshav designa a alguien que vive en medio de una comunidad que no es la suya, ocupando una condición legal y social distinta tanto del ciudadano nativo como del ger (extranjero residente) más establecido. Presente exclusivamente en textos sacerdotales y tardíos, a menudo aparece emparejado con ger o con sakir (''jornalero''), señalando una posición dependiente y algo marginal. Abraham se llama a sí mismo ger-wetoshav entre los hititas (Gn 23:4), y David repite la expresión en su oración, confesando que Israel son ''forasteros y peregrinos'' delante de Dios (1 Cr 29:15).');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H8453b', 'spa', 'habitantes de (Tisbé) — residentes de un lugar, aquí Tisbé en Galaad, que identifica el origen de Elías', 'Esta frase en 1 Reyes 17:1 identifica la ciudad natal de Elías. El texto hebreo presenta dificultades, pero la mayoría de los eruditos leen «de Tisbé de Galaad» en lugar de la lectura masorética «de los moradores de Galaad». Tisbé se identifica con la actual Istib en las tierras altas de Transjordania. La nota geográfica subraya los orígenes rústicos y agrestes de Elías: no era un profeta de corte, sino una figura curtida de la frontera, acorde con su ministerio confrontativo y sus retiros al desierto.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H8454', 'spa', 'Sabiduría sólida, discernimiento práctico; éxito duradero o ayuda eficaz — término técnico de la literatura sapiencial', 'El sustantivo תּוּשִׁיָּה es un término técnico de la tradición sapiencial de Israel que designa una sabiduría profunda y eficaz, capaz de producir resultados reales. Es ese entendimiento ingenioso que pertenece a Dios mismo: Isaías 28:29 se maravilla de que el SEÑOR ''hizo maravilloso el consejo y grande la תּוּשִׁיָּה''. Proverbios personifica a la sabiduría poseyéndola junto con el consejo (Pr 8:14) e insta al discípulo a guardarla (Pr 3:21). En Job, la palabra adquiere un matiz más concreto: cuando los planes sensatos se frustran (Job 5:12) o la ayuda se aleja (Job 6:13), תּוּשִׁיָּה apunta hacia el resultado práctico — éxito, liberación, ayuda eficaz — más que hacia la facultad en sí.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H8455', 'spa', 'garrote, maza — arma contundente para golpear, mencionada entre las armas ineficaces contra Leviatán', 'Este sustantivo designa un garrote o maza, un arma contundente para golpear. Job 41:29 lo incluye entre las armas que Leviatán considera «como paja». El término paralelo es «jabalina», lo cual sugiere que se abarcan tanto armas arrojadizas como de mano. El contexto enfatiza la invulnerabilidad de la criatura: las armas humanas son inútiles ante este símbolo de poder indomable. Ya sea que Leviatán represente un cocodrilo, un monstruo mítico del caos o un símbolo poético, el mensaje es la impotencia humana frente a las fuerzas más fieras de la creación.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H8456', 'spa', 'cortar, podar — término agrícola para eliminar sarmientos o zarcillos de la vid', 'Este raro verbo en Hifil aparece únicamente en Isaías 18:5, donde describe el acto agrícola de cortar los sarmientos o zarcillos. El contexto es el juicio de Dios como poda sobre las naciones, usando imaginería de viticultura. Formas relacionadas en hebreo tardío y arameo targúmico transmiten la idea de brotar o cortar, sugiriendo una remoción tajante y decisiva. Las glosas multilingües apuntan consistentemente a cortar o eliminar, en consonancia con la metáfora agrícola de recortar el crecimiento no deseado antes de la cosecha.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H8457', 'spa', 'Fornicación, prostitución; promiscuidad sexual y espiritual, especialmente como metáfora profética de la idolatría', 'Fornicación, prostitución; promiscuidad sexual y espiritual, especialmente como metáfora profética de la idolatría');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H8458', 'spa', 'Consejo sabio, direccion estrategica o guia prudente; usado exclusivamente en literatura sapiencial para la planificacion sensata.', 'Derivado de la imagen de dirigir un barco tirando de cuerdas, este sustantivo captura el arte de la guia sabia y el consejo estrategico. En Proverbios aparece repetidamente junto a terminos para consejeros y planes, subrayando que el liderazgo solido requiere no solo inteligencia en bruto sino la habilidad de navegar situaciones complejas. Job 37:12 extiende la metafora a la direccion soberana de Dios sobre la nube de tormenta misma, mientras que Proverbios 12:5 contrasta los consejos de los impios con los pensamientos de los justos.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H8459', 'spa', 'Toju, nombre propio: antepasado de Samuel mencionado en la genealogía levítica (1 Crónicas 6:19)', 'Este nombre propio aparece en la genealogía de Samuel en 1 Crónicas 6:19, identificando a un antepasado levítico. El nombre tiene una forma paralela en 1 Samuel 1:1, con variación textual frecuente en las genealogías hebreas. Las versiones antiguas —Septuaginta y Vulgata— lo transliteran de diversas maneras, reflejando incertidumbre sobre la pronunciación original. El nombre no está atestiguado fuera de estos pasajes, lo que hace incierta su etimología.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H8460', 'spa', 'debajo, bajo (arameo); con מִן: de debajo de', 'Esta es la forma aramea equivalente al hebreo תַּחַת, que aparece exclusivamente en Daniel y en Jeremías 10:11 (un versículo en arameo). Indica posición espacial debajo de algo, especialmente en imágenes cósmicas: ''debajo de todos los cielos'' (Dn 7:27), bajo un gran árbol (Dn 4). La forma aramea muestra los cambios vocálicos típicos respecto al hebreo bíblico, reflejando la transición lingüística del período exílico. Los traductores la vierten de manera uniforme como ''debajo de'' o ''bajo'' en todos los idiomas.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H8461', 'spa', 'tajkemonita, adjetivo gentilicio: designación étnica o de clan para uno de los valientes de David (2 Samuel 23:8)', 'Este raro gentilicio identifica a uno de los guerreros de élite de David en 2 Samuel 23:8. Los estudiosos del texto sugieren leer «el hacmonita», conectándolo con un nombre familiar mencionado en 1 Crónicas 11:11. Las versiones antiguas transliteran el término en lugar de traducirlo, lo que indica que también lo encontraban oscuro. Representa el tipo de designaciones de clan o región comunes en las listas de los guerreros de David, donde las identidades geográficas y familiares solían fusionarse.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H8462', 'spa', 'Comienzo, inicio; el punto inicial o primera fase de un periodo, evento o actividad', 'Comienzo, inicio; el punto inicial o primera fase de un periodo, evento o actividad');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H8463', 'spa', 'Enfermedades, dolencias; males graves o crónicos enviados como juicio divino o sanados por misericordia', 'Sustantivo plural que designa enfermedades o dolencias crónicas, siempre en contextos de consecuencia pactual o compasión divina. Deuteronomio advierte de terribles enfermedades sobre la tierra desobediente (Dt 29:22), y Joram muere de enfermedades incurables como castigo divino (2 Cr 21:19). Jeremías empareja ''enfermedades de hambruna'' con heridas de espada para retratar devastación total (Jer 14:18; 16:4). Sin embargo, el Salmo 103:3 celebra al Dios que ''sana todas tus enfermedades'' — la misma palabra redimida por la misericordia. El arco teológico de maldición a sanidad confiere a este término todo su peso bíblico.');